/* Picalta 5 — interface e sistemas sociais. Sem framework, compatível com a estrutura Vercel original. */
'use strict';
(function(){
  const S=window.PICALTA_STATE,E=escapeHtml,I=window.icon;
  const Q=s=>document.querySelector(s),QA=s=>[...document.querySelectorAll(s)];
  const ms=t=>t?.toMillis?t.toMillis():Number(t||0);
  const dt=t=>new Date(t).toLocaleString('pt-PT',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
  const uid=()=>S.me?.uid;
  const id=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
  const fmt=n=>new Intl.NumberFormat('pt-PT',{notation:n>9999?'compact':'standard'}).format(n||0);
  const challenges=[{id:'photo',title:'Conta a tua história',desc:'Partilha uma fotografia ou um estado.',target:1,reward:25,icon:'camera'},{id:'comment',title:'Começa uma conversa',desc:'Deixa dois comentários com significado.',target:2,reward:15,icon:'message-circle'},{id:'discover',title:'Alarga os horizontes',desc:'Explora três publicações em detalhe.',target:3,reward:20,icon:'compass'},{id:'story',title:'Um momento só teu',desc:'Partilha uma história de 24 horas.',target:1,reward:15,icon:'circle-dot'}];
  let started=false,seq=0,feedSort='recent',feedFilter='all',exploreFilter='Todas',collectionFilter='all';
  let prefs={blocked:[],muted:[],hiddenPosts:[],autoplay:true,fontScale:'normal',reduceMotion:false};
  let collections=[],drafts=[],scheduled=[],events=[],attendees={},daily={date:'',counts:{},claimed:[]};
  let errors={},unsubs=[],attendeeUnsubs={},activeOverlay=null,lastFocus=null,commentUnsub=null,commentPost=null,replyTo=null,commentSort='recent',commentEditing=null;
  let editor=null,composer=null,storyState=null,storyRaf=null,storyReplyBusy=false,searchMode='Tudo';
  const carouselIndex={},busyLikes=new Set();
  const privateDate=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');};
  const safeUrl=v=>/^(https?:|data:image\/(jpeg|png|webp|gif);|blob:|demo\/)/i.test(String(v||''))?E(v):'';
  function user(u){return S.usersCache[u]||(u===uid()?S.profile:null)||{name:'Utilizador',username:'utilizador'};}
  function avatar(u,cls=''){const d=typeof u==='string'?user(u):u;return `<span class="p-avatar ${cls}" style="--avatar-color:${E(/^#[0-9a-f]{3,8}$/i.test(d?.avatarColor||'')?d.avatarColor:'#775a9a')}">${d?.avatarUrl?`<img src="${safeUrl(d.avatarUrl)}" alt="" loading="lazy">`:E(initialsOf(d?.name))}</span>`;}
  function btn(label,attrs='',kind='btn ghost'){return `<button class="${kind}" ${attrs}>${label}</button>`;}
  function ib(name,label,attrs=''){return `<button class="icon-btn" aria-label="${E(label)}" title="${E(label)}" ${attrs}>${I(name)}</button>`;}
  function empty(title,desc,action='',ic='image'){return `<div class="p-empty">${I(ic,36)}<h3>${E(title)}</h3><p>${E(desc)}</p>${action}</div>`;}
  function errorView(key){return `<div class="inline-alert" role="alert">${I('circle-alert')}<div><b>Não foi possível carregar estes dados</b><p>Verifica a ligação e as regras do Firebase.</p></div>${btn('Tentar novamente','data-reload')}</div>`;}
  function fail(scope,e){errors[scope]=e?.message||'Falha de ligação';console.warn('[Picalta 5]',scope,e);if(Q('#p5-'+scope))Q('#p5-'+scope).innerHTML=`<div class="inline-alert">${I('circle-alert')}<span>Não foi possível carregar. Verifica a ligação e as regras do Firebase.</span>${btn('Tentar novamente','data-reload')}</div>`;}
  async function run(button,task){if(button?.disabled)return;const old=button?.innerHTML;if(button){button.disabled=true;button.setAttribute('aria-busy','true');}try{return await task();}catch(e){showError(e?.message||'Não foi possível concluir. Tenta novamente.');return false;}finally{if(button?.isConnected){button.disabled=false;button.removeAttribute('aria-busy');if(old&&button.innerHTML==='A guardar…')button.innerHTML=old;}}}
  function showError(text){const box=Q('.p-overlay .p-error');if(box){box.textContent=text;box.hidden=false;}else toast(text);}
  function clearError(){const e=Q('.p-overlay .p-error');if(e){e.hidden=true;e.textContent='';}}
  function setup(){
    const logo=`<svg class="p-mark" width="36" height="36" viewBox="0 0 36 36" fill="none" aria-label="Picalta"><rect x="1" y="1" width="34" height="34" rx="11" fill="currentColor"/><path d="M11 26V11.5h8a6 6 0 0 1 0 12h-3.5" stroke="white" stroke-width="3.4" stroke-linecap="round"/><circle cx="19.5" cy="17.5" r="2" fill="white"/></svg><span class="p-wordmark">picalta<span class="brand-dot">.</span></span>`;
    QA('.logo').forEach(el=>el.innerHTML=logo);
    Q('.sidebar .logo').insertAdjacentHTML('afterend','<span class="nav-caption">O TEU ESPAÇO</span>');
    const navigation=[['feed','house','Para ti'],['explore','compass','Explorar'],['reels','clapperboard','Reels'],['chats','message-circle','Mensagens'],['collections','bookmark','Coleções'],['events','calendar-days','Eventos'],['challenges','target','Desafios']];
    const secondary=[['studio','sliders-horizontal','Estúdio'],['games','gamepad-2','Jogos'],['music','music','Música'],['groups','users','Comunidades'],['polls','chart-column','Sondagens'],['ai','sparkles','PicalAi']];
    const navrow=a=>`<a href="#" data-nav="${a[0]}" class="${a[0]==='feed'?'active':''}">${I(a[1])}<span>${a[2]}</span>${a[0]==='challenges'||a[0]==='reels'?'<span class="nav-new">NOVO</span>':''}${a[0]==='chats'?'<span class="nav-unread" id="nav-message-count" hidden></span>':''}</a>`;
    Q('.nav').innerHTML=navigation.map(navrow).join('')+'<span class="nav-caption nav-second">DESCOBRE MAIS</span>'+secondary.map(navrow).join('');
    Q('#new-post-btn').innerHTML=I('plus',18)+'Criar publicação';
    Q('#new-story-btn').classList.add('legacy-action');Q('#new-text-btn').classList.add('legacy-action');Q('#tabbar-notif').classList.add('legacy-action');
    Q('#logout-btn').innerHTML=I('log-out',18)+'Sair da conta';
    Q('.sidebar-footer').insertAdjacentHTML('beforeend','<button class="sidebar-account" data-nav="profile" id="sidebar-account"></button>');
    Q('.viewport').insertAdjacentHTML('afterbegin',`<header class="p-topbar"><div class="top-context"><span class="top-section" id="top-section">O teu feed</span><span class="top-divider"></span><span class="top-motto">Um novo olhar, todos os dias.</span></div><div class="top-tools"><button class="global-search" data-command>${I('search',18)}<span>Pesquisar no Picalta</span><kbd>⌘ K</kbd></button>${ib('sun','Mudar tema','data-theme-proxy')}${ib('bell','Notificações','data-notif')}<button class="top-avatar" data-nav="profile" aria-label="O meu perfil" id="top-avatar"></button></div></header>`);
    Q('#view-feed').innerHTML=`<div class="home-layout"><div class="home-main"><div class="feed-intro"><div><span class="eyebrow">O TEU CANTO DA INTERNET</span><h1>O teu mundo, mais perto<span>.</span></h1><p>Momentos que vale a pena partilhar.</p></div><button class="subtle-link" data-command>${I('search',18)}<span>Descobrir</span></button></div><div class="stories-top"><b>Histórias</b><div>${btn('Criar história '+I('plus',14),'data-story-create','text-btn')} ${ib('chevron-right','Mais histórias','data-scroll-stories')}</div></div><div class="people-bar" id="people-bar" aria-label="Histórias dos teus amigos"></div><div class="quick-composer"><div class="composer-prompt"><span id="quick-avatar"></span><button data-compose>O que te inspira hoje?</button>${ib('image-plus','Adicionar fotografias','data-compose')}</div><div class="composer-shortcuts">${btn(I('image',16)+'Fotografia','data-compose','text-btn')}${btn(I('type',16)+'Pensamento','data-compose-text','text-btn')}${btn(I('circle-dot',16)+'História','data-story-create','text-btn')}<span>Sê tu. Partilha o teu mundo.</span></div></div><div class="feed-controls"><div class="feed-tabs"><button id="tab-feed-all" class="active" data-feed-tab="all">Para ti</button><button id="tab-feed-following" data-feed-tab="following">A seguir</button><button data-feed-tab="favorites">Favoritos</button></div><button class="sort-btn" data-sort-feed aria-label="Ordenar publicações">${I('sliders-horizontal',16)}<span id="feed-sort-label">Recentes</span></button></div><div id="feed-filter-note"></div><div class="feed" id="feed"></div></div><aside class="discovery-rail" id="discovery-rail" aria-label="Descobrir pessoas e atividades"></aside></div>`;
    const titles={explore:'Encontra a tua inspiração',chats:'Conversas que aproximam',games:'Uma pausa para jogar',music:'A banda sonora do teu dia',groups:'Encontra a tua comunidade',polls:'A tua opinião conta',ai:'Uma ideia puxa outra',settings:'O Picalta, à tua maneira',profile:'O teu perfil'};
    Object.entries(titles).forEach(([v,t])=>{const h=Q('#view-'+v+' .page-title');if(h)h.textContent=t;});
    Q('#view-explore').innerHTML=`<div class="section-heading"><span class="eyebrow">SAI DA TUA BOLHA</span><h1>Encontra a tua inspiração<span>.</span></h1><p>Novos lugares, novas pessoas, novas perspetivas.</p></div><div class="filter-chips" id="explore-chips"></div><div class="discover-grid" id="explore-grid"></div><div class="section-row"><h2>Pessoas para descobrir</h2><button class="text-btn" data-nav="search">Pesquisar pessoas ${I('arrow-right',16)}</button></div><div class="suggestions-list" id="suggestions"></div>`;
    ['collections','events','challenges','studio','reels'].forEach(v=>{const s=document.createElement('section');s.className='view';s.id='view-'+v;Q('.viewport').appendChild(s);});
    const mobileNav=[['feed','house','Início'],['reels','clapperboard','Reels'],['chats','message-circle','Mensagens'],['profile','user','Perfil']];
    Q('.tabbar').innerHTML=mobileNav.slice(0,2).map(navrow).join('')+`<button class="mobile-create" data-compose aria-label="Criar publicação">${I('plus',24)}</button>`+mobileNav.slice(2).map(navrow).join('')+`<button data-more aria-label="Mais opções">${I('menu',22)}<span>Mais</span></button>`;
    Q('#new-post-btn-mobile').style.setProperty('display','none','important');
    Q('#view-chats').insertAdjacentHTML('afterbegin',`<div class="section-heading"><span class="eyebrow">BONS ENCONTROS</span><h1>Conversas que aproximam<span>.</span></h1><p>Há sempre mais para contar.</p></div><div class="chat-toolbar"><label class="input-icon">${I('search',18)}<input id="chat-filter" placeholder="Procurar uma conversa" aria-label="Pesquisar conversas"></label><button class="btn ghost" data-nav="search">${I('square-pen',18)}Nova conversa</button></div>`);
    Q('#chat-window').insertAdjacentHTML('afterend',`<div class="chat-idle" id="chat-idle">${I('message-circle',44)}<h2>Uma boa conversa começa aqui.</h2><p>Escolhe uma pessoa ou descobre alguém novo.</p><button class="btn ghost" data-nav="search">Encontrar pessoas ${I('arrow-right',18)}</button></div>`);
    Q('#chat-input').maxLength=4000;Q('#chat-input').setAttribute('aria-label','Mensagem');Q('#chat-input-form button').innerHTML=I('send',19)+'<span class="sr-only">Enviar</span>';
    Q('#search-input').setAttribute('aria-label','Pesquisar pessoas');Q('#hashtag-search-input').setAttribute('aria-label','Pesquisar hashtags');
    Q('#view-settings').insertAdjacentHTML('afterbegin',`<div class="p5-settings" id="p5-settings"></div>`);
    Q('#notifications-panel').insertAdjacentHTML('afterbegin',`<div class="notif-kicker">À TUA VOLTA</div>`);
    Q('#notifications-panel').insertAdjacentHTML('beforeend',`<div class="notif-footer"><button class="text-btn" data-notif-clear>Marcar tudo como lido ${I('check-check',16)}</button></div>`);
    Q('#toast').setAttribute('aria-live','polite');
    QA('.page-head.mobile-only').forEach(el=>el.classList.add('legacy-action'));
    Q('#picalta-splash .txt').innerHTML='picalta.';
    // A entrada continua a ser a autenticação original; a demonstração é uma escolha explícita.
    Q('#login-view').insertAdjacentHTML('afterbegin',`<div class="login-art"><span class="eyebrow">PEQUENOS MOMENTOS. GRANDES LIGAÇÕES.</span><h1>A vida fica melhor<br>quando é partilhada<span>.</span></h1><p>Um espaço para as tuas fotografias, as tuas pessoas e tudo o que te inspira.</p><div class="login-photos"><img src="demo/p1.jpg" alt="Falésias junto ao oceano"><img src="demo/p2.jpg" alt="Flores e café à janela"><img src="demo/p3.jpg" alt="Uma rua de Lisboa"></div><span class="login-small">Fotografias ilustrativas geradas para a demonstração.</span></div>`);
    Q('#auth-password').closest('.field').insertAdjacentElement('afterend',Q('#forgot-password-btn'));
    Q('#google-login-btn').insertAdjacentHTML('beforebegin','<p class=\"auth-separator\">ou</p>');
    if(window.PICALTA_DEMO){Q('.top-context').insertAdjacentHTML('beforeend','<span class="demo-pill" title="Dados fictícios; alterações apenas nesta sessão">Demonstração</span>');Q('#logout-btn').textContent='Ir para a entrada';}
    Q('#new-post-btn').addEventListener('click',()=>compose());
    Q('#new-story-btn').addEventListener('click',()=>createStory());
    Q('#new-text-btn').addEventListener('click',()=>compose(null,'text'));
    Q('#more-story-btn').addEventListener('click',()=>createStory());
    if(window.PICALTA_DEMO)Q('#logout-btn').addEventListener('click',e=>{e.stopImmediatePropagation();location.href='index.html';},true);
    // Accessibilité des contrôles hérités.
    QA('input:not([aria-label]),textarea:not([aria-label])').forEach(el=>{if(!document.querySelector('label[for="'+el.id+'"]'))el.setAttribute('aria-label',el.placeholder||el.id||'Campo de texto');});
    Q('#chat-filter').addEventListener('input',()=>{const term=Q('#chat-filter').value.toLowerCase();QA('.chat-card').forEach(c=>c.hidden=!c.textContent.toLowerCase().includes(term));});
    const observe=new MutationObserver(()=>{const open=Q('#chat-window').classList.contains('active');Q('#chat-idle').hidden=open;});observe.observe(Q('#chat-window'),{attributes:true,attributeFilter:['class']});
  }
  async function init(){
    if(started)return;started=true;
    S.usersCache[uid()]={...S.profile,id:uid()};
    renderAccount();renderRail();renderStories();renderFeed();
    const watch=(key,f)=>unsubs.push(V5DATA.watch(key,f,e=>fail(key,e)));
    watch('preferences',d=>{if(d)prefs={...prefs,...d};applyPrefs();renderFeed();renderStories();if(S.view==='settings')renderPreferences();});
    watch('collections',d=>{collections=d?.items||[];if(S.view==='collections')renderCollections();});
    watch('challenges',d=>{daily=d&&d.date===privateDate()?d:{date:privateDate(),counts:{},claimed:[]};renderChallengeRail();if(S.view==='challenges')renderChallenges();});
    unsubs.push(V5DATA.watchDrafts(d=>{drafts=d;if(S.view==='studio')renderStudio();},e=>fail('drafts',e)));
    unsubs.push(V5DATA.watchScheduled(d=>{scheduled=d;if(S.view==='studio')renderStudio();processScheduled();},e=>fail('scheduled',e)));
    unsubs.push(V5DATA.watchEvents(d=>{events=d;for(const ev of d)if(!attendeeUnsubs[ev.id])attendeeUnsubs[ev.id]=V5DATA.watchAttendees(ev.id,a=>{attendees[ev.id]=a;if(S.view==='events')renderEvents();renderEventRail();},e=>fail('events',e));if(S.view==='events')renderEvents();renderEventRail();},e=>fail('events',e)));
    setInterval(processScheduled,30000);
    setInterval(()=>{if(daily.date!==privateDate()){daily={date:privateDate(),counts:{},claimed:[]};renderChallengeRail();}},60000);
    if(window.PICALTA_DEMO)S.notifications=[{text:'Bem-vindo ao teu novo Picalta. Explora sem criar conta.',when:'Modo de demonstração'},{text:'O passeio «Lisboa pela tua lente» está à tua espera.',when:'Um novo evento para descobrir'}];
    renderNotifications();
    // Modos especiais nunca fingem que existe uma IA ligada.
    if(window.PICALTA_DEMO){Q('#ai-intro').innerHTML='<b>A PicalAi precisa de uma ligação real.</b><p>Na demonstração, não são geradas respostas. Na tua instalação Vercel, mantém as variáveis da API e a autenticação Firebase.</p>';}
    const hash=location.hash.match(/^#post-(.+)$/);if(hash)setTimeout(()=>photoOpen(decodeURIComponent(hash[1])),500);
    renderPreferences();
  }
  function applyPrefs(){document.body.dataset.fontScale=prefs.fontScale||'normal';document.body.classList.toggle('reduce-motion',!!prefs.reduceMotion);}
  async function savePrefs(){await V5DATA.set('preferences',prefs);}
  function renderAccount(){if(!S.me)return;Q('#sidebar-account').innerHTML=avatar(uid())+`<span><b>${E(S.profile.name||'O teu perfil')}</b><small>@${E(S.profile.username||'perfil')}</small></span>${I('chevron-right',16)}`;Q('#top-avatar').innerHTML=avatar(uid());Q('#quick-avatar').innerHTML=avatar(uid());}
  function renderRail(){if(!S.me)return;Q('#discovery-rail').innerHTML=`<div class="rail-profile">${avatar(uid())}<div><b>${E(S.profile.name||'O teu perfil')}</b><span>@${E(S.profile.username||'perfil')}</span></div><button class="text-btn" data-nav="profile">Ver perfil</button></div><div class="rail-section" id="challenge-rail"></div><div class="rail-section"><div class="rail-heading"><h2>Novos olhares</h2><button class="text-btn" data-nav="explore">Ver todos</button></div><div id="rail-people"></div></div><div class="rail-section" id="event-rail"></div><div class="rail-footer"><span>Um espaço para seres tu.</span><div><button data-nav="settings">Definições</button><span>·</span><button data-safety>Segurança</button><span>·</span><button data-help>Ajuda</button></div><small>© ${new Date().getFullYear()} Picalta · v5.0</small>${window.PICALTA_DEMO?'<small>Perfis e conteúdos de demonstração.<br>As alterações duram esta sessão.</small>':''}</div>`;renderChallengeRail();renderSuggestedRail();renderEventRail();}
  async function renderSuggestedRail(){if(!S.me)return;let list=Object.values(S.usersCache).filter(u=>u.uid!==uid()&&!prefs.blocked.includes(u.uid)).slice(0,3);if(list.length<3)try{const a=await dbListUsers(12);a.forEach(u=>S.usersCache[u.uid||u.id]=u);list=a.filter(u=>(u.uid||u.id)!==uid()&&!prefs.blocked.includes(u.uid||u.id)).slice(0,3);}catch(e){}const box=Q('#rail-people');if(!box)return;box.innerHTML=list.length?list.map(u=>`<div class="rail-person">${avatar(u)}<button class="person-info" data-goto-profile="${E(u.uid||u.id)}"><b>${E(u.name)}</b><span>@${E(u.username)}</span></button><button class="follow-icon ${S.myFollowing.includes(u.uid||u.id)?'is-following':''}" aria-label="${S.myFollowing.includes(u.uid||u.id)?'Deixar de seguir':'Seguir'} ${E(u.name)}" title="${S.myFollowing.includes(u.uid||u.id)?'A seguir':'Seguir'}" data-v5-follow="${E(u.uid||u.id)}">${I(S.myFollowing.includes(u.uid||u.id)?'user-check':'user-plus',18)}</button></div>`).join(''):empty('Mais pessoas em breve','As sugestões aparecem quando outras pessoas aderirem.','','users');}
  function renderChallengeRail(){const box=Q('#challenge-rail');if(!box)return;const ch=challenges.find(c=>!(daily.claimed||[]).includes(c.id))||challenges[0];const n=Math.min(ch.target,daily.counts?.[ch.id]||0);box.innerHTML=`<div class="daily-card"><div class="daily-kicker">${I('zap',16)} UM POUCO MAIS TU <span>+${ch.reward} XP</span></div><h3>Um dia, uma nova<br>perspetiva.</h3><p>${E(ch.desc)}</p><div class="daily-progress"><span style="width:${n/ch.target*100}%"></span></div><button data-nav="challenges">${n>=ch.target?'Recolher recompensa':'Ver desafios de hoje'} ${I('arrow-right',17)}</button></div>`;}
  function renderEventRail(){const box=Q('#event-rail');if(!box)return;const ev=events.find(e=>e.startsAt>Date.now());box.innerHTML=`<div class="rail-heading"><h2>Fora do ecrã</h2><button class="text-btn" data-nav="events">Explorar</button></div>${ev?`<button class="rail-event" data-event-open="${E(ev.id)}"><img src="${safeUrl(ev.cover||'demo/c3.jpg')}" alt=""><span class="event-date"><b>${new Date(ev.startsAt).getDate()}</b><small>${new Date(ev.startsAt).toLocaleDateString('pt-PT',{month:'short'})}</small></span><div><b>${E(ev.title)}</b><span>${I('map-pin',14)}${E(ev.location.split(',')[0])}</span></div></button>`:`<div class="rail-quiet"><p>Leva as boas ligações para fora do ecrã.</p><button class="text-btn" data-event-create>Criar o primeiro encontro ${I('arrow-right',16)}</button></div>`}`;}
  async function tickChallenge(key){
    if(!uid())return;try{const today=privateDate();const result=await __fsFns.runTransaction(db,async tx=>{const ref=V5DATA.ref('challenges'),snap=await tx.get(ref),cur=snap.exists()&&snap.data().date===today?snap.data():{date:today,counts:{},claimed:[]};const def=challenges.find(c=>c.id===key);if(!def)return cur;cur.counts=cur.counts||{};cur.counts[key]=Math.min(def.target,(cur.counts[key]||0)+1);tx.set(ref,cur);return cur;});daily=result;renderChallengeRail();}catch(e){console.warn(e);}
  }
  function filteredPosts(){let p=S.posts.filter(p=>p.type!=='reel'&&!prefs.blocked.includes(p.uid)&&!prefs.muted.includes(p.uid)&&!prefs.hiddenPosts.includes(p.id));if(S.feedTab==='following')p=p.filter(p=>S.myFollowing.includes(p.uid));if(S.feedTab==='favorites')p=p.filter(p=>S.myFavorites.includes(p.id));if(S.feedTab==='hashtag')p=p.filter(p=>(p.hashtags||[]).some(h=>h.toLowerCase()==='#'+String(S.currentHashtag).toLowerCase()));if(feedSort==='popular')p=[...p].sort((a,b)=>(b.likes||[]).length-(a.likes||[]).length);return p;}
  function postCard(p){
    const u=user(p.uid),liked=(p.likes||[]).includes(uid()),fav=S.myFavorites.includes(p.id),pics=p.images?.length?p.images:p.imageUrl?[{url:p.imageUrl,alt:p.caption||'Fotografia partilhada'}]:[],idx=Math.min(carouselIndex[p.id]||0,Math.max(0,pics.length-1));
    return `<article class="post p-post" data-post-id="${E(p.id)}"><header class="post-head">${avatar(u)}<div class="post-user"><a href="#" data-goto-profile="${E(p.uid)}">${E(u.name)} ${u.verified?I('badge-check',14):''}</a><span>${E(p.location||'@'+u.username)}<span class="meta-dot">·</span>${E(timeAgo(p.createdAt))}</span></div>${ib('ellipsis','Opções da publicação','data-post-menu="'+E(p.id)+'"')}</header>${pics.length?`<div class="p-carousel" data-carousel="${E(p.id)}"><button class="photo-open" data-photo-open="${E(p.id)}" aria-label="Ver fotografia em ecrã inteiro"><img class="post-image" src="${safeUrl(pics[idx].url)}" alt="${E(pics[idx].alt||p.caption||'Fotografia partilhada')}" ${S.posts.indexOf(p)>0?'loading="lazy"':''} decoding="async"></button>${pics.length>1?`<span class="photo-count">${idx+1} / ${pics.length}</span><button class="carousel-arrow prev" data-slide="${E(p.id)}" data-dir="-1" aria-label="Fotografia anterior">${I('chevron-left',18)}</button><button class="carousel-arrow next" data-slide="${E(p.id)}" data-dir="1" aria-label="Fotografia seguinte">${I('chevron-right',18)}</button><div class="carousel-dots">${pics.map((_,i)=>`<button class="${i===idx?'active':''}" data-dot="${E(p.id)}" data-index="${i}" aria-label="Fotografia ${i+1}"></button>`).join('')}</div>`:''}<div class="double-like" aria-hidden="true">${I('heart',72)}</div></div>`:`<div class="post-text-content">${E(p.text||'')}${p.mood?`<span class="mood-badge">${E(p.mood)}</span>`:''}</div>`}<div class="post-actions"><button class="icon-btn like-btn ${liked?'liked':''}" data-like="${E(p.id)}" aria-label="${liked?'Retirar gosto':'Gostar'}" aria-pressed="${liked}">${I('heart',23)}</button>${ib('message-circle','Abrir comentários','data-comments-open="'+E(p.id)+'"')}${ib('send','Partilhar publicação','data-v5-share="'+E(p.id)+'"')}<span class="post-actions-spacer"></span><button class="icon-btn fav-btn ${fav?'liked':''}" data-fav="${E(p.id)}" aria-label="${fav?'Remover dos favoritos':'Guardar nos favoritos'}" aria-pressed="${fav}">${I('bookmark',22)}</button></div><div class="post-meta"><button class="likes-line" data-likes-list="${E(p.id)}">${(p.likes||[]).length?`<span class="mini-likers">${(p.likes||[]).slice(0,3).map(x=>avatar(x)).join('')}</span>`:''}<b>${fmt((p.likes||[]).length)} ${(p.likes||[]).length===1?'pessoa gostou':'pessoas gostaram'}</b></button>${pics.length&&p.caption?`<p class="post-caption"><b>${E(u.username)}</b> ${E(p.caption)}</p>`:''}${(p.hashtags||[]).length?`<div class="post-hashtags">${p.hashtags.map(h=>`<a href="#" data-hashtag="${E(h.replace(/^#/,''))}">${E(h)}</a>`).join(' ')}</div>`:''}<button class="open-comments-text" data-comments-open="${E(p.id)}">${S.commentsCache[p.id]?.length?'Ver '+S.commentsCache[p.id].length+' comentários':'Ver comentários e conversar'}</button></div><div class="post-comment-preview">${avatar(uid())}<button data-comments-open="${E(p.id)}">Acrescenta um comentário…</button>${ib('smile','Comentar com uma reação','data-comments-open="'+E(p.id)+'"')}</div></article>`;
  }
  function renderFeed(){
    if(!uid()||!Q('#feed'))return;if(!S.feedLoaded){renderFeedSkeleton();return;}
    const p=filteredPosts();Q('#feed').innerHTML=p.length?p.map(postCard).join(''):empty(S.feedTab==='favorites'?'Guarda o que te inspira':S.feedTab==='following'?'O teu círculo começa contigo':'Um novo começo','Partilha um momento ou descobre pessoas com um olhar parecido com o teu.',btn('Explorar pessoas','data-nav="explore"','btn'),S.feedTab==='favorites'?'bookmark':'camera');
    QA('[data-feed-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.feedTab===S.feedTab);b.setAttribute('aria-pressed',String(b.dataset.feedTab===S.feedTab));});
    const note=Q('#feed-filter-note');if(note)note.innerHTML=S.feedTab==='hashtag'?`<div class="filter-note">A explorar #${E(S.currentHashtag)} <button data-feed-reset aria-label="Limpar filtro">${I('x',16)}</button></div>`:'';
    if(S.view==='explore')renderExplore();
    if(window.PICALTA_REELS)window.PICALTA_REELS.refresh();
  }
  async function like(postId){if(busyLikes.has(postId))return;const p=S.posts.find(p=>p.id===postId);if(!p)return;busyLikes.add(postId);const was=(p.likes||[]).includes(uid()),old=[...(p.likes||[])];p.likes=was?old.filter(x=>x!==uid()):[...old,uid()];updatePostLikes(p);try{await dbToggleLike(postId,uid(),was);}catch(e){p.likes=old;updatePostLikes(p);toast('Não foi possível guardar o gosto.');}finally{busyLikes.delete(postId);}}
  function updatePostLikes(p){QA(`[data-post-id="${CSS.escape(p.id)}"]`).forEach(el=>{const liked=p.likes.includes(uid());const b=el.querySelector('[data-like]');if(b){b.classList.toggle('liked',liked);b.setAttribute('aria-pressed',String(liked));b.setAttribute('aria-label',liked?'Retirar gosto':'Gostar');}const l=el.querySelector('.likes-line b');if(l)l.textContent=fmt(p.likes.length)+' pessoas gostaram';const rc=el.querySelector('.reel-like-count');if(rc)rc.textContent=fmt(p.likes.length);});}
  function slide(postId,direct,index){const p=S.posts.find(x=>x.id===postId);if(!p)return;const n=p.images?.length||1;carouselIndex[postId]=index===undefined?((carouselIndex[postId]||0)+direct+n)%n:index;const article=Q(`[data-post-id="${CSS.escape(postId)}"]`);if(article){const st=window.scrollY;article.outerHTML=postCard(p);window.scrollTo(0,st);}if(activeOverlay==='lightbox')renderLightbox(p);}
  function renderStories(){
    const box=Q('#people-bar');if(!box||!uid())return;
    const stories=(S.stories||[]).filter(s=>!prefs.blocked.includes(s.uid)&&!prefs.muted.includes(s.uid));
    const authors=[...new Set(stories.map(s=>s.uid))];
    box.innerHTML=`<button class="story-create-card" data-story-create><span class="story-create-photo">${avatar(uid())}<span class="story-plus">${I('plus',17)}</span></span><b>A tua história</b><small>Partilha um momento</small></button>`+authors.map(u=>{const a=stories.find(s=>s.uid===u),seen=(S._seenStories||[]).includes(a.id);return `<button class="story-card ${seen?'seen':''}" data-view-story="${E(u)}" style="--story-bg:${E(a.color||'#6d517b')}">${a.imageUrl?`<img class="story-cover" src="${safeUrl(a.imageUrl)}" alt="História de ${E(user(u).name)}" loading="lazy">`:`<span class="story-cover-text">${E((a.text||'').slice(0,40))}</span>`}<span class="story-card-shade"></span><span class="story-card-avatar">${avatar(u)}</span><b>${u===uid()?'A tua história':E(user(u).name.split(' ')[0])}</b><span class="story-indicator"></span></button>`;}).join('');
    // O snapshot das histórias pode chegar antes dos autores.
    const missing=authors.filter(u=>!S.usersCache[u]);if(missing.length)Promise.all(missing.map(loadUser)).then(()=>renderStories()).catch(()=>{});
  }
  function modal(kind,title,body,opts={}){
    if(activeOverlay==='composer'&&composer?.dirty&&kind!=='editor')saveDraft(true);
    closeOverlay(true);lastFocus=document.activeElement;activeOverlay=kind;
    const el=document.createElement('div');el.className='p-overlay '+(opts.drawer?'is-drawer':'')+' '+(opts.className||'');el.id='p5-overlay';el.innerHTML=`<section class="p-dialog ${opts.wide?'wide':''} ${opts.drawer?'p-drawer':''}" role="dialog" aria-modal="true" aria-labelledby="p5-dialog-title" tabindex="-1"><header class="dialog-head"><div><span class="eyebrow">${E(opts.kicker||'O TEU PICALTA')}</span><h2 id="p5-dialog-title">${E(title)}</h2></div>${ib('x','Fechar janela','data-close-overlay')}</header><div class="p-error" role="alert" hidden></div><div class="dialog-body">${body}</div></section>`;document.body.appendChild(el);document.body.classList.add('overlay-open');el.addEventListener('click',e=>{if(e.target===el)closeOverlay();});setTimeout(()=>{const target=el.querySelector('input:not([type="file"]), textarea, .dialog-head button');target?.focus();},30);return el;
  }
  function closeOverlay(silent=false){
    if(!silent&&activeOverlay==='composer'&&composer?.dirty)saveDraft(true);
    if(commentUnsub){commentUnsub();commentUnsub=null;}if(activeOverlay==='story')stopStory();
    Q('#p5-overlay')?.remove();document.body.classList.remove('overlay-open');activeOverlay=null;commentPost=null;replyTo=null;commentEditing=null;
    if(!silent&&lastFocus?.isConnected)lastFocus.focus();
  }
  function photoOpen(postId){const p=S.posts.find(p=>p.id===postId);if(!p)return;if(p.type==='reel'&&window.PICALTA_REELS){closeOverlay(true);navigate('reels');window.PICALTA_REELS.open(p.id);return;}tickChallenge('discover');modal('lightbox','Um olhar mais de perto','<div id="lightbox-body"></div>',{wide:true,className:'lightbox-overlay',kicker:p.location||'FOTOGRAFIA'});renderLightbox(p);}
  function renderLightbox(p){const box=Q('#lightbox-body');if(!box)return;const pics=p.images?.length?p.images:p.imageUrl?[{url:p.imageUrl,alt:p.caption}]:[];const idx=carouselIndex[p.id]||0;box.innerHTML=`<div class="lightbox-photo">${pics.length?`<img src="${safeUrl(pics[idx].url)}" alt="${E(pics[idx].alt||'Fotografia')}" id="lightbox-image">`:`<p>${E(p.text)}</p>`}${pics.length>1?`<button class="carousel-arrow prev" data-slide="${E(p.id)}" data-dir="-1" aria-label="Foto anterior">${I('chevron-left')}</button><button class="carousel-arrow next" data-slide="${E(p.id)}" data-dir="1" aria-label="Foto seguinte">${I('chevron-right')}</button><span class="photo-count">${idx+1} / ${pics.length}</span>`:''}</div><div class="lightbox-details"><div class="row">${avatar(p.uid)}<div><b>${E(user(p.uid).name)}</b><small>@${E(user(p.uid).username)}</small></div><button class="icon-btn" data-lightbox-zoom aria-label="Ampliar fotografia">${I('zoom-in')}</button></div><p>${E(p.caption||p.text||'')}</p><div class="lightbox-bottom">${btn(I('heart',18)+'Gostar','data-like="'+E(p.id)+'"')}${btn(I('message-circle',18)+'Comentários','data-comments-open="'+E(p.id)+'"','btn')}</div></div>`;}
  function postMenu(postId){const p=S.posts.find(x=>x.id===postId);if(!p)return;const mine=p.uid===uid();modal('postmenu','Esta publicação',`<div class="menu-list">${btn(I('folder-plus')+'Guardar numa coleção','data-add-collection="'+E(p.id)+'"','menu-row')}${btn(I('link')+'Copiar ligação','data-copy-post="'+E(p.id)+'"','menu-row')}${mine?btn(I('pen-line')+'Editar legenda','data-edit-caption="'+E(p.id)+'"','menu-row')+btn(I('trash-2')+'Apagar publicação','data-delete-post="'+E(p.id)+'"','menu-row danger-text'):btn(I('eye-off')+'Ocultar esta publicação','data-hide-post="'+E(p.id)+'"','menu-row')+btn(I('volume-x')+'Silenciar @'+E(user(p.uid).username),'data-mute-user="'+E(p.uid)+'"','menu-row')+btn(I('flag')+'Denunciar publicação','data-report-post="'+E(p.id)+'"','menu-row danger-text')+btn(I('ban')+'Bloquear esta pessoa','data-block-user="'+E(p.uid)+'"','menu-row danger-text')}</div>`,{kicker:'TU ESCOLHES O QUE VÊS'});}
  function ask(title,desc,action,label='Confirmar',danger=false){modal('confirm',title,`<p class="dialog-description">${E(desc)}</p><div class="dialog-actions">${btn('Cancelar','data-close-overlay')}${btn(E(label),'id="confirm-action"',danger?'btn danger':'btn')}</div>`);Q('#confirm-action').onclick=e=>run(e.currentTarget,action);}
  async function deletePost(postId){const p=S.posts.find(p=>p.id===postId);if(!p||p.uid!==uid())return;ask(p.type==='reel'?'Apagar este reel?':'Apagar esta publicação?',p.type==='reel'?'O vídeo deixará de estar disponível para a comunidade. Esta ação não pode ser desfeita.':'A fotografia e a publicação deixarão de aparecer no feed. Esta ação não pode ser desfeita.',async()=>{await dbDeletePost(postId);closeOverlay();toast('Publicação apagada.');},'Apagar publicação',true);}
  function share(postId){const p=S.posts.find(x=>x.id===postId);if(!p)return;const url=new URL(location.href);url.hash='post-'+postId;modal('share','Partilha este momento',`<div class="share-preview">${p.imageUrl?`<img src="${safeUrl(p.imageUrl)}" alt="">`:I('type',30)}<div><b>${E(user(p.uid).name)}</b><p>${E((p.caption||p.text||'').slice(0,110))}</p></div></div><label class="field"><span>Ligação da publicação</span><input id="share-url" value="${E(url.href)}" readonly></label><div class="dialog-actions">${btn(I('copy',18)+'Copiar ligação','data-copy-current','btn')}${navigator.share?btn(I('share-2',18)+'Mais opções','data-native-share="'+E(p.id)+'"'):''}</div><small class="muted">Quem abrir precisa de aceder ao mesmo Picalta. Os dados da demonstração são fictícios.</small>`);}
  async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Ligação copiada.');}catch(e){const el=Q('#share-url');if(el){el.select();el.focus();toast('Seleciona e copia a ligação.');}else toast('O navegador não permitiu copiar. Abre a opção Partilhar.');}}
  async function editCaption(postId){const p=S.posts.find(x=>x.id===postId);if(!p||p.uid!==uid())return;modal('editcaption','As palavras também contam',`<label class="field"><span>${p.imageUrl?'Legenda':'Pensamento'}</span><textarea id="edit-caption" maxlength="2200" rows="5">${E(p.imageUrl?p.caption:p.text)}</textarea></label><div class="dialog-actions">${btn('Cancelar','data-close-overlay')}${btn('Guardar alterações','data-caption-save="'+E(p.id)+'"','btn')}</div>`);}
  function comments(postId){
    const p=S.posts.find(x=>x.id===postId);if(!p)return;
    commentSort='recent';replyTo=null;modal('comments','A conversa continua',`<div class="comment-post-context">${p.imageUrl?`<img src="${safeUrl(p.imageUrl)}" alt="">`:I('type',28)}<div><b>${E(user(p.uid).name)}</b><p>${E((p.caption||p.text||'').slice(0,140))}</p></div></div><div class="comment-toolbar"><span id="comment-count">A carregar comentários…</span><label>Ordenar<select id="comment-sort" aria-label="Ordenar comentários"><option value="recent">Mais recentes</option><option value="popular">Mais gostados</option><option value="oldest">Primeiro os antigos</option></select></label></div><div class="comment-threads" id="comment-threads"><div class="skel" style="height:160px"></div></div><div class="reply-context" id="reply-context" hidden></div><form id="p5-comment-form" class="p5-comment-form">${avatar(uid())}<label class="comment-input-label"><span class="sr-only">O teu comentário</span><textarea id="p5-comment-input" rows="1" placeholder="Acrescenta o teu olhar…" maxlength="2000"></textarea></label><button class="comment-send" type="submit" aria-label="Publicar comentário">${I('send',19)}</button></form><div class="comment-hint"><button class="text-btn" data-comment-mention>${I('at-sign',15)}Mencionar</button><span id="comment-char-count">0 / 2000</span></div>`,{drawer:true,kicker:'COMENTÁRIOS'});
    commentPost=postId;
    commentUnsub=dbWatchComments(postId,async snap=>{S.commentsCache[postId]=snap.docs.map(d=>({id:d.id,...d.data()}));const authors=[...new Set(S.commentsCache[postId].map(c=>c.uid))];try{await Promise.all(authors.filter(u=>!S.usersCache[u]).map(loadUser));}catch(e){}if(commentPost===postId)renderComments();});
    Q('#comment-sort').onchange=e=>{commentSort=e.target.value;renderComments();};
    Q('#p5-comment-input').oninput=e=>{Q('#comment-char-count').textContent=e.target.value.length+' / 2000';e.target.style.height='auto';e.target.style.height=Math.min(120,e.target.scrollHeight)+'px';};
    Q('#p5-comment-form').onsubmit=e=>{e.preventDefault();const input=Q('#p5-comment-input'),text=input.value.trim();if(!text)return;run(Q('.comment-send'),async()=>{clearError();if(commentEditing){await V5DATA.commentEdit(postId,commentEditing,text);}else{await V5DATA.comment(postId,text,replyTo);tickChallenge('comment');xpOnComment();}input.value='';input.style.height='auto';Q('#comment-char-count').textContent='0 / 2000';replyTo=null;commentEditing=null;Q('#reply-context').hidden=true;toast('Comentário guardado.');});};
  }
  function renderComments(){const box=Q('#comment-threads');if(!box||!commentPost)return;const list=(S.commentsCache[commentPost]||[]).filter(c=>!prefs.blocked.includes(c.uid));let roots=list.filter(c=>!c.replyTo||!list.some(x=>x.id===c.replyTo));if(commentSort==='popular')roots.sort((a,b)=>(b.likes||[]).length-(a.likes||[]).length);else roots.sort((a,b)=>(ms(b.createdAt)-ms(a.createdAt))*(commentSort==='oldest'?-1:1));
    const item=(c,nested=false)=>{const u=user(c.uid),liked=(c.likes||[]).includes(uid());return `<article class="comment-item ${nested?'is-reply':''}">${avatar(c.uid)}<div class="comment-content"><div class="comment-name"><b>${E(u.name)}</b><span>${E(timeAgo(c.createdAt))}${c.editedAt?' · editado':''}</span></div><p>${E(c.text)}</p><div class="comment-row-actions"><button data-comment-reply="${E(c.replyTo||c.id)}" data-author="${E(c.uid)}">Responder</button><button class="${liked?'liked':''}" data-comment-like="${E(c.id)}" aria-label="${liked?'Retirar gosto do comentário':'Gostar do comentário'}">${I('heart',13)}${(c.likes||[]).length||''}</button>${c.uid===uid()?`<button data-comment-edit="${E(c.id)}">Editar</button>`:''}${c.uid===uid()||S.posts.find(p=>p.id===commentPost)?.uid===uid()?`<button data-comment-delete="${E(c.id)}" aria-label="Apagar comentário">${I('trash-2',13)}</button>`:''}</div></div></article>`;};
    Q('#comment-count').textContent=list.length+' '+(list.length===1?'comentário':'comentários');box.innerHTML=roots.length?roots.map(c=>`<div class="comment-thread">${item(c)}${list.filter(r=>r.replyTo===c.id).sort((a,b)=>ms(a.createdAt)-ms(b.createdAt)).map(r=>item(r,true)).join('')}</div>`).join(''):empty('O primeiro olhar pode ser o teu','Começa uma conversa com um comentário.','','message-circle');}
  function replyComment(cid,author){replyTo=cid;commentEditing=null;Q('#reply-context').hidden=false;Q('#reply-context').innerHTML=`${I('reply',15)}A responder a <b>@${E(user(author).username)}</b><button class="icon-btn" data-cancel-reply aria-label="Cancelar resposta">${I('x',16)}</button>`;Q('#p5-comment-input').focus();}
  function story(author){
    const all=(S.stories||[]).filter(s=>!prefs.blocked.includes(s.uid)&&!prefs.muted.includes(s.uid));const authors=[...new Set(all.map(s=>s.uid))];const ordered=authors.flatMap(u=>all.filter(s=>s.uid===u).sort((a,b)=>ms(a.createdAt)-ms(b.createdAt)));let idx=ordered.findIndex(s=>s.uid===author);if(idx<0)return;
    modal('story','Histórias','<div id="p-story-body"></div>',{className:'p-story-overlay',kicker:'AGORA, À TUA VOLTA'});storyState={items:ordered,idx,elapsed:0,last:performance.now(),paused:!prefs.autoplay,hold:false,posting:false};renderStory();animateStory();
  }
  function stopStory(){if(storyRaf)cancelAnimationFrame(storyRaf);storyRaf=null;storyState=null;}
  function storyMove(delta){if(!storyState)return;const idx=storyState.idx+delta;if(idx>=storyState.items.length){closeOverlay();return;}if(idx<0){storyState.elapsed=0;return;}storyState.idx=idx;storyState.elapsed=0;storyState.last=performance.now();renderStory();}
  function renderStory(){if(!storyState)return;const s=storyState.items[storyState.idx],u=user(s.uid);S._seenStories=[...new Set([...(S._seenStories||[]),s.id])];const items=storyState.items.filter(x=>x.uid===s.uid);const cur=items.findIndex(x=>x.id===s.id);Q('#p-story-body').innerHTML=`<div class="story-stage" style="background:${E(s.color||'#3b2c43')}"><div class="story-bars">${items.map((x,i)=>`<span><i style="width:${i<cur?100:0}%" ${i===cur?'id="story-progress-active"':''}></i></span>`).join('')}</div><div class="story-top"><button class="story-author" data-goto-profile="${E(s.uid)}">${avatar(u)}<span><b>${E(u.name)}</b><small>${E(timeAgo(s.createdAt))}</small></span></button><div>${ib(storyState.paused?'play':'pause',storyState.paused?'Reproduzir história':'Pausar história','data-story-pause')}${s.uid===uid()?ib('trash-2','Apagar história','data-story-delete="'+E(s.id)+'"'):''}${ib('x','Fechar história','data-close-overlay')}</div></div>${s.imageUrl?`<img class="story-full-img" src="${safeUrl(s.imageUrl)}" alt="${E(s.caption||'História de '+u.name)}">`:`<div class="story-text-display">${E(s.text||'')}</div>`}<button class="story-tap story-prev" data-story-prev aria-label="História anterior"></button><button class="story-tap story-next" data-story-next aria-label="Próxima história"></button>${s.caption?`<p class="story-caption">${E(s.caption)}</p>`:''}<div class="story-bottom"><div class="story-reactions">${[['heart','Adorei'],['sparkles','Incrível'],['flame','Espetacular']].map(([ic,l])=>`<button data-story-react="${l}" aria-label="${l}" title="${l}">${I(ic,22)}</button>`).join('')}<span id="story-reaction-status" aria-live="polite"></span></div>${s.uid!==uid()?`<form id="story-reply-form"><label class="sr-only" for="story-reply-input">Responder à história</label><input id="story-reply-input" maxlength="1000" placeholder="Responder a ${E(u.name.split(' ')[0])}…"><button type="submit" aria-label="Enviar resposta">${I('send',20)}</button></form>`:`<div class="own-story-note">${I('clock',16)}Visível durante 24 horas</div>`}</div></div><div class="story-desktop-controls">${ib('chevron-left','História anterior','data-story-prev')}<span>← → para navegar · espaço para pausar</span>${ib('chevron-right','Próxima história','data-story-next')}</div>`;
    const input=Q('#story-reply-input');if(input){input.onfocus=()=>{if(storyState)storyState.hold=true;};input.onblur=()=>{if(storyState){storyState.hold=false;storyState.last=performance.now();}};Q('#story-reply-form').onsubmit=async e=>{e.preventDefault();if(storyReplyBusy||!input.value.trim())return;const text=input.value.trim();storyReplyBusy=true;await run(e.submitter,async()=>{const cid=await dbGetOrCreateChat(uid(),s.uid);await dbSendMessage(cid,uid(),'Resposta à história: '+text);input.value='';toast('Resposta enviada por mensagem privada.');});storyReplyBusy=false;};}
    const stage=Q('.story-stage');let sx=0,sy=0;stage.addEventListener('touchstart',e=>{sx=e.touches[0].clientX;sy=e.touches[0].clientY;},{passive:true});stage.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-sx,dy=e.changedTouches[0].clientY-sy;if(Math.abs(dx)>60)storyMove(dx<0?1:-1);else if(dy>100)closeOverlay();},{passive:true});
    stage.addEventListener('pointerdown',e=>{if(e.target.closest('.story-full-img,.story-text-display')&&storyState)storyState.hold=true;});stage.addEventListener('pointerup',()=>{if(storyState){storyState.hold=false;storyState.last=performance.now();}});stage.addEventListener('pointerleave',()=>{if(storyState&&!Q('#story-reply-input')?.matches(':focus'))storyState.hold=false;});renderStories();}
  function animateStory(t){if(!storyState)return;const now=t||performance.now();if(!storyState.paused&&!storyState.hold&&!document.hidden)storyState.elapsed+=Math.min(now-storyState.last,150);storyState.last=now;const el=Q('#story-progress-active');if(el)el.style.width=Math.min(100,storyState.elapsed/6500*100)+'%';if(storyState.elapsed>=6500)storyMove(1);if(storyState)storyRaf=requestAnimationFrame(animateStory);}
  function createStory(){
    modal('storycreate','O teu próximo momento',`<div class="story-compose-layout"><div class="story-creation-preview" id="story-create-preview" style="background:#6d517b"><span>Uma história<br>começa contigo.</span></div><div class="story-compose-tools"><div class="segmented"><button class="active" data-story-type="text">${I('type',16)}Texto</button><button data-story-type="photo">${I('image',16)}Fotografia</button></div><div id="story-text-tools"><label class="field"><span>O que queres contar?</span><textarea id="story-text" maxlength="280" rows="4" placeholder="Um pensamento, uma descoberta…"></textarea></label><div class="field"><span>Cor de fundo</span><div class="color-options">${['#6d517b','#345a51','#aa674e','#34476b','#b5843d','#2b2926'].map((c,i)=>`<button style="background:${c}" data-story-color="${c}" class="${i===0?'active':''}" aria-label="Fundo ${['ameixa','verde','terracota','azul','ocre','grafite'][i]}"></button>`).join('')}</div></div></div><div id="story-photo-tools" hidden><label class="p-upload" for="story-photo-input">${I('image-plus',30)}<b>Escolher fotografia</b><span>JPG, PNG ou WebP · até 12 MB</span></label><input type="file" accept="image/jpeg,image/png,image/webp" id="story-photo-input" hidden></div><label class="field"><span>Uma pequena legenda <small>opcional</small></span><input id="story-caption-v5" maxlength="140" placeholder="Dá contexto ao teu momento"></label><p class="info-line">${I('clock',17)}A tua história desaparece ao fim de 24 horas.</p></div></div><div class="dialog-actions">${btn('Cancelar','data-close-overlay')}${btn('Publicar história '+I('arrow-right',17),'id="story-publish-v5"','btn')}</div>`,{wide:true,kicker:'HISTÓRIAS'});
    const data={type:'text',color:'#6d517b',imageUrl:null};
    const preview=()=>{const p=Q('#story-create-preview');p.style.background=data.color;p.innerHTML=data.type==='photo'&&data.imageUrl?`<img src="${safeUrl(data.imageUrl)}" alt="Pré-visualização da história">`:`<span>${E(Q('#story-text').value||'Uma história\ncomeça contigo.').replace(/\n/g,'<br>')}</span>`;};
    Q('#story-text').oninput=preview;
    QA('[data-story-type]').forEach(b=>b.onclick=()=>{data.type=b.dataset.storyType;QA('[data-story-type]').forEach(x=>x.classList.toggle('active',x===b));Q('#story-text-tools').hidden=data.type!=='text';Q('#story-photo-tools').hidden=data.type!=='photo';preview();});
    QA('[data-story-color]').forEach(b=>b.onclick=()=>{data.color=b.dataset.storyColor;QA('[data-story-color]').forEach(x=>x.classList.toggle('active',x===b));preview();});
    Q('#story-photo-input').onchange=e=>run(null,async()=>{const f=e.target.files[0];if(!f)return;validateImage(f);data.imageUrl=await compress(f,1200,0.85);preview();});
    Q('#story-publish-v5').onclick=e=>run(e.currentTarget,async()=>{clearError();const text=Q('#story-text').value.trim(),caption=Q('#story-caption-v5').value.trim();if(data.type==='text'&&!text)throw new Error('Escreve algo para a tua história.');if(data.type==='photo'&&!data.imageUrl)throw new Error('Escolhe uma fotografia.');const imageUrl=data.type==='photo'?await V5DATA.upload(data.imageUrl,'stories'):null;await V5DATA.story({imageUrl,text:data.type==='text'?text:null,color:data.color,caption});closeOverlay();toast('O teu momento já está no ar.');xpOnStory();tickChallenge('story');});
  }
  /* ---------- Estúdio: carrosséis, edição, rascunhos e agendamento ---------- */
  function validateImage(f){if(!/^image\/(jpeg|png|webp)$/.test(f.type))throw new Error('Escolhe uma imagem JPG, PNG ou WebP.');if(f.size>12*1024*1024)throw new Error('Cada fotografia pode ter até 12 MB.');}
  function fileData(f){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Não foi possível ler o ficheiro.'));r.readAsDataURL(f);});}
  function imageLoad(src){return new Promise((resolve,reject)=>{const img=new Image();img.crossOrigin='anonymous';img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('Não foi possível abrir esta imagem.'));img.src=src;});}
  async function compress(source,max=1000,quality=.8){const src=typeof source==='string'?source:await fileData(source),im=await imageLoad(src);const ratio=Math.min(1,max/Math.max(im.naturalWidth,im.naturalHeight));const c=document.createElement('canvas');c.width=Math.round(im.naturalWidth*ratio);c.height=Math.round(im.naturalHeight*ratio);c.getContext('2d').drawImage(im,0,0,c.width,c.height);try{return c.toDataURL('image/jpeg',quality);}catch(e){throw new Error('O navegador bloqueou a exportação da imagem. Usa um ficheiro local.');}}
  function compose(draft=null,type='photo'){
    if(draft){composer={id:draft.id,type:draft.type||'photo',caption:draft.caption||'',location:draft.location||'',images:(draft.images||[]).map(x=>({...x})),selected:0,dirty:false,scheduled:false,dueAt:'',version:0};}
    else if(!composer||activeOverlay!=='editor')composer={id:'draft_'+id(),type,caption:'',location:'',images:[],selected:0,dirty:false,scheduled:false,dueAt:'',version:0};
    renderComposer();
  }
  function renderComposer(){if(!composer)return;const c=composer;
    modal('composer',c.type==='text'?'Uma ideia para partilhar':'Cria o teu próximo momento',`<div class="compose-tabs segmented"><button data-compose-mode="photo" class="${c.type==='photo'?'active':''}">${I('images',17)}Fotografias</button><button data-compose-mode="text" class="${c.type==='text'?'active':''}">${I('type',17)}Pensamento</button></div><div class="composer-layout ${c.type==='text'?'text-only':''}"><div class="composer-media" id="composer-media" ${c.type==='text'?'hidden':''}><div id="composer-preview"></div><div id="composer-thumbs" class="composer-thumbs"></div><label class="add-more-photo" for="composer-files">${I('plus',16)}Adicionar fotografias <span id="composer-image-count">${c.images.length} / 6</span></label><input type="file" id="composer-files" accept="image/jpeg,image/png,image/webp" multiple hidden></div><div class="composer-fields"><div class="compose-author">${avatar(uid())}<div><b>${E(S.profile.name||'O teu perfil')}</b><span>${I('globe',12)}Visível para a comunidade</span></div></div><label class="field"><span>${c.type==='text'?'O que te inspira?':'Uma legenda para o momento'}</span><textarea id="compose-caption" rows="5" maxlength="2200" placeholder="Uma história, uma ideia, um lugar…">${E(c.caption)}</textarea><span class="field-counter" id="compose-char-count">${c.caption.length} / 2200</span></label><label class="field"><span>${I('map-pin',15)}Localização <small>opcional</small></span><input id="compose-location" maxlength="100" value="${E(c.location)}" placeholder="Onde aconteceu?"></label><div class="compose-extra"><span>${I('hash',16)}Usa #hashtags para seres descoberto.</span></div><button class="schedule-toggle ${c.scheduled?'active':''}" data-compose-schedule>${I('calendar',18)}<span>Publicar mais tarde</span>${I('chevron-down',16)}</button><div id="compose-schedule-panel" ${c.scheduled?'':'hidden'}><label class="field"><span>Data e hora local</span><input type="datetime-local" id="compose-date" value="${E(c.dueAt)}"></label><p class="schedule-warning">${I('info',16)}O agendamento é processado enquanto a app está aberta. Se a fechares, a publicação será enviada quando regressares.</p></div><p class="draft-save-status" id="draft-save-status">${I('cloud',14)}${window.PICALTA_DEMO?'Rascunhos só nesta sessão de demonstração':'Os rascunhos guardam uma cópia comprimida das fotos'}</p></div></div><div class="dialog-actions compose-footer"><button class="btn ghost" id="compose-save-draft">${I('save',16)}Guardar rascunho</button><button class="btn" id="compose-publish">${c.scheduled?I('calendar',17)+'Agendar':I('send',17)+'Publicar momento'}</button></div>`,{wide:true,kicker:'ESTÚDIO CRIATIVO'});
    renderComposerMedia();
    const mark=()=>{c.caption=Q('#compose-caption').value;c.location=Q('#compose-location').value;c.dueAt=Q('#compose-date')?.value||'';c.dirty=true;c.version++;Q('#compose-char-count').textContent=c.caption.length+' / 2200';Q('#draft-save-status').textContent='A guardar o teu rascunho…';clearTimeout(compose._save);compose._save=setTimeout(()=>saveDraft(true),1400);};
    Q('#compose-caption').oninput=mark;Q('#compose-location').oninput=mark;Q('#compose-date').onchange=mark;
    Q('#compose-date').min=localDateTime(Date.now()+60000);
    Q('#composer-files').onchange=e=>addFiles(e.target.files);
    const drop=Q('#composer-media');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag-over');};drop.ondragleave=()=>drop.classList.remove('drag-over');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag-over');addFiles(e.dataTransfer.files);};
    Q('#compose-save-draft').onclick=e=>run(e.currentTarget,async()=>{await saveDraft(false);closeOverlay(true);composer=null;navigate('studio');toast('O teu rascunho está guardado.');});
    Q('#compose-publish').onclick=e=>run(e.currentTarget,publishComposer);
  }
  function localDateTime(value){const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
  function renderComposerMedia(){if(!composer||!Q('#composer-preview'))return;const c=composer,sel=c.images[c.selected];Q('#composer-preview').innerHTML=sel?`<div class="composer-photo"><img src="${safeUrl(sel.dataUrl)}" alt="Pré-visualização da fotografia ${c.selected+1}"><span class="compose-photo-count">${c.selected+1} / ${c.images.length}</span><button class="edit-photo-btn" data-photo-edit="${c.selected}">${I('sliders-horizontal',16)}Editar fotografia</button></div><label class="alt-field"><span>Texto alternativo</span><input id="compose-alt" maxlength="180" value="${E(sel.alt||'')}" placeholder="Descreve a imagem para quem não a consegue ver"></label>`:`<label class="p-upload main-upload" for="composer-files">${I('image-plus',40)}<h3>Um momento merece<br>mais do que ficar na galeria.</h3><p>Arrasta as tuas fotografias ou escolhe os ficheiros.</p><span class="btn">Escolher fotografias ${I('arrow-right',16)}</span><small>Até 6 fotos · JPG, PNG ou WebP · 12 MB por foto</small></label>`;
    Q('#composer-thumbs').innerHTML=c.images.map((x,i)=>`<div class="compose-thumb ${i===c.selected?'selected':''}"><button data-compose-select="${i}" aria-label="Selecionar fotografia ${i+1}"><img src="${safeUrl(x.dataUrl)}" alt="Fotografia ${i+1}"></button><div><button data-compose-move="${i}" data-dir="-1" aria-label="Mover fotografia para a esquerda" ${i===0?'disabled':''}>${I('chevron-left',12)}</button><button data-compose-remove="${i}" aria-label="Remover fotografia ${i+1}">${I('x',12)}</button><button data-compose-move="${i}" data-dir="1" aria-label="Mover fotografia para a direita" ${i===c.images.length-1?'disabled':''}>${I('chevron-right',12)}</button></div></div>`).join('');
    Q('#composer-image-count').textContent=c.images.length+' / 6';
    if(Q('#compose-alt'))Q('#compose-alt').oninput=e=>{sel.alt=e.target.value;c.dirty=true;c.version++;clearTimeout(compose._save);compose._save=setTimeout(()=>saveDraft(true),1400);};
  }
  async function addFiles(files){if(!composer)return;const list=[...files];if(composer.images.length+list.length>6){showError('Podes partilhar até seis fotografias por publicação.');return;}const c=composer;await run(Q('#compose-publish'),async()=>{clearError();for(const f of list){validateImage(f);const dataUrl=await compress(f,1600,.86);if(composer!==c)return;c.images.push({dataUrl,alt:'',name:f.name});}c.selected=c.images.length-1;c.dirty=true;c.version++;renderComposerMedia();saveDraft(true);});}
  async function saveDraft(quiet=true){
    clearTimeout(compose._save);const c=composer;if(!c||(!c.caption.trim()&&!c.images.length))return;
    const version=c.version;
    const data={type:c.type,caption:c.caption,location:c.location,images:await Promise.all(c.images.map(async x=>({dataUrl:await compress(x.dataUrl,640,.65),alt:x.alt||''})))};
    try{await V5DATA.draftSave(c.id,data);if(composer===c&&c.version===version)c.dirty=false;const status=Q('#draft-save-status');if(status&&composer===c)status.textContent='Rascunho guardado · '+new Date().toLocaleTimeString('pt-PT',{hour:'2-digit',minute:'2-digit'});}
    catch(e){if(quiet){const status=Q('#draft-save-status');if(status)status.textContent='Rascunho não guardado. Mantém esta janela aberta e tenta guardar novamente.';}else throw e;}
  }
  async function publishComposer(){
    const c=composer;if(!c)return;clearError();
    if(c.type==='photo'&&!c.images.length)throw new Error('Escolhe pelo menos uma fotografia.');if(c.type==='text'&&!c.caption.trim())throw new Error('Escreve o teu pensamento antes de o partilhares.');
    const due=c.scheduled?new Date(Q('#compose-date').value).getTime():null;
    if(c.scheduled&&(!Number.isFinite(due)||due<Date.now()+60000))throw new Error('Escolhe uma data pelo menos um minuto no futuro.');
    const pub=Q('#compose-publish');pub.textContent=c.scheduled?'A agendar…':'A publicar…';
    try{const images=c.type==='photo'?await withProgress(Promise.all(c.images.map(async x=>({url:await V5DATA.upload(x.dataUrl),alt:x.alt||c.caption.slice(0,180)})))):[];
      const post={imageUrl:images[0]?.url||null,images,caption:c.type==='photo'?c.caption.trim():'',text:c.type==='text'?c.caption.trim():'',location:c.location.trim(),hashtags:[...new Set(c.caption.match(/#[\p{L}\p{N}_]+/gu)||[])]};
      if(c.scheduled)await V5DATA.schedule(post,due);else await V5DATA.createPost(post);
      clearTimeout(compose._save);c.dirty=false;
      try{await V5DATA.draftDelete(c.id);}catch(e){console.warn('Rascunho publicado não removido',e);}
      composer=null;closeOverlay(true);if(c.scheduled){navigate('studio');toast('Publicação agendada. Mantém a app aberta para envio à hora marcada.');}else{navigate('feed');S.feedTab='all';renderFeed();toast('Mais um momento para guardar.');xpOnPost();tickChallenge('photo');unlockAchievement('first_post');}
    }finally{if(pub.isConnected)pub.innerHTML=c.scheduled?I('calendar',17)+'Agendar':I('send',17)+'Publicar momento';}
  }
  async function processScheduled(){if(processScheduled.busy||!uid())return;processScheduled.busy=true;try{for(const item of scheduled.filter(x=>x.dueAt<=Date.now()&&x.status==='pending')){const done=await V5DATA.publishScheduled(item.id);if(done){toast('A tua publicação agendada foi enviada.');xpOnPost();tickChallenge('photo');}}}catch(e){console.warn('[Agendamento]',e);errors.scheduled=e.message;}finally{processScheduled.busy=false;}}
  const filterDefs=[['original','Original','none'],['warm','Dourado','sepia(.24) saturate(1.12) contrast(1.03)'],['film','Película','sepia(.2) contrast(.92) saturate(.8)'],['mono','Monocromático','grayscale(1) contrast(1.12)'],['cool','Brisa','saturate(.8) hue-rotate(8deg) contrast(1.05)'],['vivid','Vivo','saturate(1.4) contrast(1.08)']];
  async function editPhoto(index){const photo=composer?.images[index];if(!photo)return;const im=await imageLoad(photo.dataUrl);editor={index,im,filter:'original',brightness:100,contrast:100,saturation:100,rotation:0,zoom:100,x:0,y:0,ratio:'original'};
    modal('editor','Dá-lhe o teu olhar',`<div class="photo-editor-layout"><div class="editor-canvas-wrap"><canvas id="photo-editor-canvas" aria-label="Pré-visualização da fotografia editada"></canvas></div><div class="editor-tools"><div class="editor-heading"><b>Filtros</b><button class="text-btn" data-editor-reset>Repor</button></div><div class="filter-options">${filterDefs.map(([k,l,f])=>`<button class="${k==='original'?'active':''}" data-editor-filter="${k}"><img src="${safeUrl(photo.dataUrl)}" alt="" style="filter:${f}"><span>${l}</span></button>`).join('')}</div><b>Enquadramento</b><div class="ratio-options">${[['original','Original'],['1','1:1'],['0.8','4:5'],['1.7778','16:9']].map(([k,l])=>`<button data-editor-ratio="${k}" class="${k==='original'?'active':''}">${l}</button>`).join('')}</div><div class="editor-rotate">${btn(I('rotate-ccw',17)+'Rodar à esquerda','data-editor-rotate="-90"','text-btn')}${btn(I('rotate-cw',17)+'Rodar à direita','data-editor-rotate="90"','text-btn')}</div>${[['brightness','Luz',50,150],['contrast','Contraste',50,150],['saturation','Cor',0,200],['zoom','Aproximação',100,200],['x','Posição horizontal',-100,100],['y','Posição vertical',-100,100]].map(([k,l,min,max])=>`<label class="slider-field"><span>${l}<output id="out-${k}">${editor[k]}</output></span><input type="range" id="edit-${k}" data-editor-adjust="${k}" min="${min}" max="${max}" value="${editor[k]}" aria-label="${l}"></label>`).join('')}</div></div><div class="dialog-actions"><button class="btn ghost" data-editor-back>Cancelar edição</button><button class="btn" id="editor-apply">${I('check',17)}Aplicar à fotografia</button></div>`,{wide:true,kicker:'EDITOR DE FOTOGRAFIA'});
    QA('[data-editor-adjust]').forEach(el=>el.oninput=()=>{editor[el.dataset.editorAdjust]=Number(el.value);Q('#out-'+el.dataset.editorAdjust).value=el.value;drawEditor();});
    Q('#editor-apply').onclick=e=>run(e.currentTarget,async()=>{const c=Q('#photo-editor-canvas');let result;try{result=c.toDataURL('image/jpeg',.88);}catch(err){throw new Error('A exportação foi bloqueada pelo navegador. Usa uma fotografia local.');}composer.images[index].dataUrl=result;composer.dirty=true;composer.version++;editor=null;renderComposer();saveDraft(true);});drawEditor();
  }
  function drawEditor(){if(!editor||!Q('#photo-editor-canvas'))return;const e=editor,im=e.im,rotation=((e.rotation%360)+360)%360;const rotated=document.createElement('canvas');rotated.width=rotation%180?im.naturalHeight:im.naturalWidth;rotated.height=rotation%180?im.naturalWidth:im.naturalHeight;const r=rotated.getContext('2d');r.translate(rotated.width/2,rotated.height/2);r.rotate(rotation*Math.PI/180);r.drawImage(im,-im.naturalWidth/2,-im.naturalHeight/2);
    const ar=e.ratio==='original'?rotated.width/rotated.height:Number(e.ratio);let sw=rotated.width,sh=sw/ar;if(sh>rotated.height){sh=rotated.height;sw=sh*ar;}sw/=e.zoom/100;sh/=e.zoom/100;const sx=(rotated.width-sw)/2+(rotated.width-sw)/2*(e.x/100),sy=(rotated.height-sh)/2+(rotated.height-sh)/2*(e.y/100);const canvas=Q('#photo-editor-canvas');canvas.width=Math.round(Math.min(1600,1600*ar));canvas.height=Math.round(canvas.width/ar);const ctx=canvas.getContext('2d');const preset=filterDefs.find(f=>f[0]===e.filter)?.[2];ctx.filter=(preset==='none'?'':preset+' ')+`brightness(${e.brightness}%) contrast(${e.contrast}%) saturate(${e.saturation}%)`;ctx.drawImage(rotated,sx,sy,sw,sh,0,0,canvas.width,canvas.height);
  }
  function renderStudio(){const posts=S.posts.filter(p=>p.uid===uid()),likes=posts.reduce((n,p)=>n+(p.likes||[]).length,0),commentsCount=posts.reduce((n,p)=>n+(S.commentsCache[p.id]?.length||0),0),photos=posts.reduce((n,p)=>n+(p.images?.length||(p.imageUrl?1:0)),0);Q('#view-studio').innerHTML=`<div class="section-heading with-action"><div><span class="eyebrow">UM ESPAÇO PARA CRIAR</span><h1>O teu estúdio<span>.</span></h1><p>Da primeira ideia ao próximo momento.</p></div><button class="btn" data-compose>${I('plus',17)}Criar publicação</button></div><div class="studio-metrics"><div><span>Publicações</span><b>${posts.length}</b><small>${photos} ${photos===1?"fotografia partilhada":"fotografias partilhadas"}</small></div><div><span>Gostos recebidos</span><b>${fmt(likes)}</b><small>Nas publicações do teu feed</small></div><div><span>A tua comunidade</span><b>${S.myFollowing.length}</b><small>Pessoas que segues</small></div><div><span>O teu progresso</span><b>${fmt(S.player.xp)}<em>XP</em></b><small>Nível ${S.player.level||1}</small></div></div><div class="studio-tabs"><button class="active" data-studio-tab="drafts">${I('pen-line',17)}Rascunhos <span>${drafts.length}</span></button><button data-studio-tab="scheduled">${I('calendar',17)}Agendados <span>${scheduled.length}</span></button><button data-studio-tab="stats">${I('trending-up',17)}Estatísticas</button></div><div id="studio-tab-content"></div>`;renderStudioTab(renderStudio._tab||'drafts');}
  function renderStudioTab(tab){renderStudio._tab=tab;QA('[data-studio-tab]').forEach(b=>b.classList.toggle('active',b.dataset.studioTab===tab));const box=Q('#studio-tab-content');if(!box)return;
    if(tab==='drafts')box.innerHTML=errors.drafts?`<div class="inline-alert">Não foi possível carregar os rascunhos. Verifica as regras Firebase.</div>`:drafts.length?`<div class="draft-grid">${drafts.map(d=>`<article class="draft-card"><button class="draft-cover" data-draft-open="${E(d.id)}">${d.images?.[0]?`<img src="${safeUrl(d.images[0].dataUrl)}" alt="Fotografia do rascunho">`:`<span>${I('type',30)}${E((d.caption||'Uma nova ideia').slice(0,80))}</span>`}<span class="draft-badge">Rascunho</span></button><div><b>${E((d.caption||'Um momento por terminar').slice(0,70))}</b><span>Guardado ${timeAgo(d.updatedAt)} · ${d.images?.length||0} fotos</span><div class="row">${btn('Continuar a criar '+I('arrow-right',16),'data-draft-open="'+E(d.id)+'"','text-btn')}${ib('trash-2','Apagar rascunho','data-draft-delete="'+E(d.id)+'"')}</div></div></article>`).join('')}</div>`:empty('As boas ideias merecem tempo','Os teus rascunhos ficam aqui, prontos para quando a inspiração voltar.',btn('Começar uma ideia','data-compose','btn'),'pen-line');
    if(tab==='scheduled')box.innerHTML=`<div class="inline-info">${I('info',20)}<div><b>O teu calendário, sem pressa.</b><p>As publicações são enviadas quando a app está aberta. Se estiver fechada à hora marcada, serão enviadas ao regressares. A hora apresentada é a do teu dispositivo.</p></div></div>`+(errors.scheduled?'<div class="inline-alert">Não foi possível carregar ou processar o agendamento.</div>':scheduled.length?scheduled.map(s=>`<article class="scheduled-card">${s.post.images?.[0]?`<img src="${safeUrl(s.post.images[0].url)}" alt="Fotografia agendada">`:`<span class="scheduled-text-icon">${I('type',25)}</span>`}<div><b>${E(s.post.caption||s.post.text||'Fotografia sem legenda')}</b><span>${I('calendar',15)}${E(dt(s.dueAt))}</span><small>${s.dueAt<Date.now()?'A aguardar envio nesta sessão':'Agendada · mantém a app aberta'}</small></div>${ib('x','Cancelar agendamento','data-schedule-cancel="'+E(s.id)+'"')}</article>`).join(''):empty('Dá espaço aos próximos momentos','Escolhe «Publicar mais tarde» ao criar uma publicação.',btn('Preparar publicação','data-compose','btn'),'calendar'));
    if(tab==='stats')renderStats();
  }
  function renderStats(){const box=Q('#studio-tab-content');if(!box)return;const posts=S.posts.filter(p=>p.uid===uid());const top=[...posts].sort((a,b)=>(b.likes||[]).length-(a.likes||[]).length).slice(0,5);const max=Math.max(1,...top.map(p=>(p.likes||[]).length));const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const key=d.toDateString();return {label:d.toLocaleDateString('pt-PT',{weekday:'short'}),n:posts.filter(p=>new Date(ms(p.createdAt)).toDateString()===key).length};});const dmax=Math.max(1,...days.map(d=>d.n));box.innerHTML=`<div class="stats-layout"><section class="stats-panel"><div class="section-row"><h2>Os teus últimos 7 dias</h2><span>Publicações</span></div><div class="activity-chart" role="img" aria-label="Publicações por dia: ${E(days.map(d=>d.label+' '+d.n).join(', '))}">${days.map(d=>`<div><b>${d.n}</b><span class="activity-track"><i style="height:${Math.max(3,d.n/dmax*100)}%"></i></span><small>${E(d.label)}</small></div>`).join('')}</div></section><section class="stats-panel"><h2>Momentos que aproximaram</h2><p class="muted">As tuas publicações com mais gostos.</p>${top.length?top.map(p=>`<button class="top-post-row" data-photo-open="${E(p.id)}">${p.imageUrl?`<img src="${safeUrl(p.imageUrl)}" alt="">`:I('type',25)}<div><b>${E((p.caption||p.text||'Sem legenda').slice(0,60))}</b><span class="stat-like-bar"><i style="width:${(p.likes||[]).length/max*100}%"></i></span></div><span>${(p.likes||[]).length} ${I('heart',14)}</span></button>`).join(''):empty('Ainda estás a começar','As tuas publicações vão dar vida a este espaço.','','trending-up')}</section></div><p class="data-note">${I('info',15)}Dados calculados a partir das publicações carregadas no feed (até 60). Não incluem impressões, alcance ou visualizações. ${window.PICALTA_DEMO?'Nesta demonstração, os dados são fictícios.':''}</p>`;}
  /* ---------- Coleções privadas ---------- */
  function collectionCover(c){const photos=c.postIds.map(x=>S.posts.find(p=>p.id===x)).filter(p=>p?.imageUrl).slice(0,4);return photos.length?`<div class="collection-collage count-${photos.length}">${photos.map(p=>`<img src="${safeUrl(p.imageUrl)}" alt="Fotografia da coleção" loading="lazy">`).join('')}</div>`:`<div class="collection-no-photo">${I('bookmark',38)}</div>`;}
  function renderCollections(){Q('#view-collections').innerHTML=`<div class="section-heading with-action"><div><span class="eyebrow">O QUE FICA CONTIGO</span><h1>As tuas coleções<span>.</span></h1><p>Guarda o que te inspira. Volta quando quiseres.</p></div><button class="btn" data-collection-create>${I('folder-plus',18)}Nova coleção</button></div><div class="collection-private">${I('lock',15)}Só tu podes ver as tuas coleções.</div><div class="collection-tabs"><button class="${collectionFilter==='all'?'active':''}" data-collection-filter="all">Todas as coleções</button><button class="${collectionFilter==='favorites'?'active':''}" data-collection-filter="favorites">${I('bookmark',16)}Todos os favoritos <span>${S.myFavorites.length}</span></button></div><div id="collections-content"></div>`;
    const box=Q('#collections-content');if(collectionFilter==='favorites'){const posts=S.posts.filter(p=>S.myFavorites.includes(p.id));box.innerHTML=posts.length?`<div class="discover-grid">${posts.map(p=>exploreTile(p)).join('')}</div>`:empty('O teu próximo favorito está por aí','Toca no marcador de uma publicação para a guardares aqui.',btn('Explorar fotografias','data-nav="explore"','btn'),'bookmark');return;}
    box.innerHTML=collections.length?`<div class="collections-grid">${collections.map(c=>`<article class="collection-card"><button class="collection-cover" data-collection-open="${E(c.id)}">${collectionCover(c)}</button><div class="collection-card-meta"><button data-collection-open="${E(c.id)}"><h2>${E(c.name)}</h2><span>${c.postIds.length} ${c.postIds.length===1?'momento guardado':'momentos guardados'}</span></button>${ib('ellipsis','Gerir coleção '+c.name,'data-collection-menu="'+E(c.id)+'"')}</div></article>`).join('')}<button class="collection-new-card" data-collection-create>${I('folder-plus',32)}<b>Uma nova inspiração</b><span>Cria uma coleção só tua</span></button></div>`:empty('Há coisas que merecem ficar','Cria uma coleção e organiza os teus lugares, ideias e fotografias favoritas.',btn('Criar a primeira coleção','data-collection-create','btn'),'folder-plus');
  }
  function nameDialog(title,value,callback){modal('name',title,`<label class="field"><span>Nome da coleção</span><input id="collection-name" maxlength="60" placeholder="Ex.: Lugares para ir" value="${E(value||'')}"></label><div class="dialog-actions">${btn('Cancelar','data-close-overlay')}${btn('Guardar coleção','id="collection-name-save"','btn')}</div>`);Q('#collection-name-save').onclick=e=>run(e.currentTarget,async()=>{const name=Q('#collection-name').value.trim();if(!name)throw new Error('Dá um nome à tua coleção.');await callback(name);closeOverlay();renderCollections();});}
  function collectionCreate(postId){nameDialog('Um lugar para a inspiração','',async name=>{collections=[...collections,{id:'col_'+id(),name,postIds:postId?[postId]:[]}];await V5DATA.set('collections',{items:collections});toast('Coleção criada.');});}
  function addToCollection(postId){modal('pickcollection','Onde queres guardar?',`<div class="collection-picker">${collections.map(c=>`<button data-collection-add="${E(c.id)}" data-post="${E(postId)}">${I(c.postIds.includes(postId)?'circle-check':'folder',24)}<span><b>${E(c.name)}</b><small>${c.postIds.length} momentos</small></span>${I(c.postIds.includes(postId)?'check':'plus',18)}</button>`).join('')}</div><button class="new-collection-inline" data-collection-create-for="${E(postId)}">${I('folder-plus',21)}Criar uma nova coleção</button>`);}
  function openCollection(idc){const c=collections.find(x=>x.id===idc);if(!c)return;const posts=c.postIds.map(x=>S.posts.find(p=>p.id===x)).filter(Boolean);modal('collectiondetail',c.name,`<p class="collection-private">${I('lock',15)}${posts.length} momentos · coleção privada</p>${posts.length?`<div class="collection-detail-grid">${posts.map(p=>`<article>${exploreTile(p)}<button class="text-btn" data-collection-remove="${E(c.id)}" data-post="${E(p.id)}">${I('x',14)}Remover</button></article>`).join('')}</div>`:empty('Ainda cabe muita inspiração aqui','Guarda publicações através do menu de três pontos.','','bookmark')}`,{wide:true,kicker:'A TUA COLEÇÃO'});}
  /* ---------- Descoberta visual ---------- */
  function exploreTile(p){return `<button class="explore-tile" data-photo-open="${E(p.id)}">${p.imageUrl?`<img src="${safeUrl(p.imageUrl)}" alt="${E(p.images?.[0]?.alt||p.caption||'Fotografia')}" loading="lazy">`:`<span class="explore-text">${E((p.text||'').slice(0,140))}</span>`}${(p.images?.length||0)>1?`<span class="tile-stack">${I('layers',18)}</span>`:''}${p.type==='reel'?`<span class="tile-stack">${I('clapperboard',18)}</span>`:''}<span class="tile-overlay"><b>${E(user(p.uid).name)}</b><span>${I('heart',16)}${(p.likes||[]).length} ${I('message-circle',16)}</span></span></button>`;}
  function renderExplore(){const chips=['Todas','Natureza','Fotografia','Cidades','Música','Aventura'];Q('#explore-chips').innerHTML=chips.map(c=>`<button class="${c===exploreFilter?'active':''}" data-explore-filter="${c}">${c}</button>`).join('');let p=S.posts.filter(x=>!prefs.blocked.includes(x.uid)&&!prefs.muted.includes(x.uid));const terms={Natureza:['natureza','oceano','surf','mar'],Fotografia:['fotografia','analogico'],Cidades:['lisboa','cidade','portugal'],Música:['musica'],Aventura:['aventura','trilho']};if(exploreFilter!=='Todas')p=p.filter(x=>(terms[exploreFilter]||[]).some(t=>(x.caption+' '+(x.hashtags||[]).join(' ')+' '+x.location).toLowerCase().includes(t)));Q('#explore-grid').innerHTML=p.length?p.map(exploreTile).join(''):empty('Há mais para descobrir','Experimenta outra categoria ou publica o teu primeiro momento.',btn('Ver todas','data-explore-filter="Todas"','btn'),'compass');}
  /* ---------- Eventos e presenças ---------- */
  let eventFilter='upcoming';
  function renderEvents(){const now=Date.now();const list=events.filter(e=>!prefs.blocked.includes(e.uid)&&(eventFilter==='going'?(attendees[e.id]||[]).some(a=>a.uid===uid()):eventFilter==='past'?e.startsAt<now:e.startsAt>=now));Q('#view-events').innerHTML=`<div class="section-heading with-action"><div><span class="eyebrow">AS MELHORES LIGAÇÕES SÃO REAIS</span><h1>Encontramo-nos por aí<span>?</span></h1><p>Transforma um interesse em comum num bom encontro.</p></div><button class="btn" data-event-create>${I('plus',18)}Criar evento</button></div><div class="filter-chips event-filters">${[['upcoming','Próximos encontros'],['going','Vou participar'],['past','Já aconteceram']].map(([k,l])=>`<button data-event-filter="${k}" class="${k===eventFilter?'active':''}">${l}</button>`).join('')}</div><div id="p5-events">${errors.events?'<div class="inline-alert">Não foi possível carregar os eventos. Verifica a ligação e as regras Firebase.</div>':list.length?`<div class="events-grid">${list.map(eventCard).join('')}</div>`:empty('Há sempre uma boa razão para sair',eventFilter==='going'?'Os eventos onde confirmares presença aparecem aqui.':'Cria um encontro para a comunidade. Um passeio, uma sessão de fotografia, um café.',btn('Criar um encontro','data-event-create','btn'),'calendar-days')}</div>`;}
  function eventCard(e){const going=(attendees[e.id]||[]).some(a=>a.uid===uid()),d=new Date(e.startsAt);return `<article class="event-card"><button class="event-cover" data-event-open="${E(e.id)}">${e.cover?`<img src="${safeUrl(e.cover)}" alt="Local do evento" loading="lazy">`:`<div class="event-cover-pattern">${I('calendar-days',44)}<span>JUNTOS, FORA DO ECRÃ.</span></div>`}<span class="event-date"><b>${d.getDate()}</b><small>${d.toLocaleDateString('pt-PT',{month:'short'})}</small></span></button><div class="event-card-body"><span class="event-time">${d.toLocaleDateString('pt-PT',{weekday:'long'})} · ${d.toLocaleTimeString('pt-PT',{hour:'2-digit',minute:'2-digit'})}</span><button class="event-title" data-event-open="${E(e.id)}"><h2>${E(e.title)}</h2></button><p>${I('map-pin',15)}${E(e.location)}</p><div class="event-card-foot"><span>${(attendees[e.id]||[]).length} confirmados</span><button class="btn ${going?'ghost':''} small" data-event-rsvp="${E(e.id)}" aria-pressed="${going}">${I(going?'check':'plus',16)}${going?'Vou participar':'Participar'}</button></div></div></article>`;}
  function createEvent(){modal('eventcreate','Uma boa razão para sair',`<form id="create-event-form"><label class="field"><span>Nome do encontro</span><input id="event-title" maxlength="100" placeholder="Ex.: Fotopasseio por Lisboa" required></label><div class="form-pair"><label class="field"><span>Data e hora local</span><input type="datetime-local" id="event-date" min="${localDateTime(Date.now()+60000)}" required></label><label class="field"><span>Local de encontro</span><input id="event-location" maxlength="160" placeholder="Um sítio fácil de encontrar" required></label></div><label class="field"><span>O que vai acontecer?</span><textarea id="event-description" maxlength="1000" rows="4" placeholder="Conta-nos o que tens em mente…"></textarea></label><p class="info-line">${I('globe',16)}O teu evento ficará visível para a comunidade.</p><div class="dialog-actions">${btn('Cancelar','data-close-overlay')}${btn('Criar encontro '+I('arrow-right',17),'type="submit"','btn')}</div></form>`,{wide:true,kicker:'UM NOVO ENCONTRO'});Q('#create-event-form').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{await V5DATA.eventCreate({title:Q('#event-title').value.trim(),description:Q('#event-description').value.trim(),location:Q('#event-location').value.trim(),startsAt:new Date(Q('#event-date').value).getTime()});closeOverlay();navigate('events');toast('O teu encontro já está no calendário.');});};}
  function openEvent(eid){const e=events.find(x=>x.id===eid);if(!e)return;const going=(attendees[eid]||[]).some(a=>a.uid===uid());modal('eventdetail',e.title,`${e.cover?`<img class="event-detail-cover" src="${safeUrl(e.cover)}" alt="Local do evento">`:''}<div class="event-detail-info"><div>${I('calendar',20)}<span><b>${E(dt(e.startsAt))}</b><small>Hora do teu dispositivo</small></span></div><div>${I('map-pin',20)}<span><b>${E(e.location)}</b><small>Local de encontro</small></span></div></div><p class="event-description">${E(e.description||'Um encontro para conhecer a comunidade e partilhar bons momentos.')}</p><div class="event-attendees"><b>${(attendees[eid]||[]).length} pessoas confirmadas</b><div>${(attendees[eid]||[]).slice(0,8).map(a=>avatar(a.uid)).join('')}</div></div><div class="dialog-actions">${btn(I('download',17)+'Adicionar ao calendário','data-event-ics="'+E(eid)+'"')}${btn(I(going?'check':'plus',17)+(going?'Cancelar presença':'Vou participar'),'data-event-rsvp="'+E(eid)+'"','btn '+(going?'ghost':''))}</div>`,{wide:true,kicker:'FORA DO ECRÃ'});}
  async function rsvp(eid,button){await run(button,async()=>{const going=(attendees[eid]||[]).some(a=>a.uid===uid());await V5DATA.eventRSVP(eid,!going);if(activeOverlay==='eventdetail')openEvent(eid);toast(going?'Presença cancelada.':'Contamos contigo neste encontro.');});}
  function downloadICS(eid){const ev=events.find(x=>x.id===eid);if(!ev)return;const esc=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,m=>'\\'+m);const when=t=>new Date(t).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const data=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Picalta//Eventos//PT','BEGIN:VEVENT','UID:'+ev.id+'@picalta','DTSTAMP:'+when(Date.now()),'DTSTART:'+when(ev.startsAt),'DTEND:'+when(ev.startsAt+7200000),'SUMMARY:'+esc(ev.title),'LOCATION:'+esc(ev.location),'DESCRIPTION:'+esc(ev.description),'END:VEVENT','END:VCALENDAR'].join('\r\n');download(new Blob([data],{type:'text/calendar;charset=utf-8'}),'picalta-evento.ics');}
  function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  /* ---------- Desafios e estatísticas ---------- */
  function renderChallenges(){const done=challenges.filter(c=>(daily.claimed||[]).includes(c.id)).length;Q('#view-challenges').innerHTML=`<div class="section-heading"><span class="eyebrow">PEQUENOS PASSOS, NOVOS OLHARES</span><h1>Hoje, faz diferente<span>.</span></h1><p>Um convite diário para partilhar, conversar e descobrir.</p></div><div class="challenge-banner"><div><span>O TEU DIA NO PICALTA</span><h2>Mais do que passar o tempo.<br>Faz o tempo contar.</h2><p>${done} de ${challenges.length} recompensas recolhidas hoje.</p></div><div class="challenge-level"><b>${S.player.level||1}</b><span>O TEU NÍVEL</span><small>${fmt(S.player.xp)} XP</small></div></div><div class="challenge-grid">${challenges.map(c=>{const n=Math.min(c.target,daily.counts?.[c.id]||0),claimed=daily.claimed?.includes(c.id),ready=n>=c.target;return `<article class="challenge-card ${claimed?'completed':''}"><div class="challenge-card-top">${I(c.icon,26)}<span>+${c.reward} XP</span></div><h2>${E(c.title)}</h2><p>${E(c.desc)}</p><div class="challenge-progress"><i style="width:${n/c.target*100}%"></i></div><div class="challenge-card-bottom"><span>${n} / ${c.target}</span><button class="btn ${ready&&!claimed?'':'ghost'} small" ${claimed?'disabled':''} ${ready&&!claimed?'data-challenge-claim="'+c.id+'"':'data-challenge-start="'+c.id+'"'}>${claimed?I('check',15)+'Recolhida':ready?'Recolher recompensa':'Começar '+I('arrow-right',15)}</button></div></article>`;}).join('')}</div><p class="data-note">${I('clock',16)}Os desafios renovam-se à meia-noite, de acordo com a hora do teu dispositivo. As recompensas são virtuais e não têm valor monetário.</p>`;}
  /* ---------- Segurança e preferências ---------- */
  function renderPreferences(){const box=Q('#p5-settings');if(!box)return;box.innerHTML=`<div class="section-heading"><span class="eyebrow">O TEU ESPAÇO, AS TUAS ESCOLHAS</span><h1>À tua maneira<span>.</span></h1><p>Um Picalta que te faz sentir em casa.</p></div><div class="settings-card preference-card"><h2>A tua experiência</h2><div class="preference-row"><div><b>Reproduzir histórias automaticamente</b><span>Passar para o próximo momento sem tocar.</span></div><label class="switch"><input type="checkbox" data-pref="autoplay" ${prefs.autoplay?'checked':''} aria-label="Reprodução automática de histórias"><span></span></label></div><div class="preference-row"><div><b>Reduzir movimento</b><span>Uma experiência com menos animações.</span></div><label class="switch"><input type="checkbox" data-pref="reduceMotion" ${prefs.reduceMotion?'checked':''} aria-label="Reduzir movimento"><span></span></label></div><div class="preference-row"><div><b>Tamanho do texto</b><span>Escolhe a leitura mais confortável.</span></div><select data-pref="fontScale" aria-label="Tamanho do texto"><option value="normal" ${prefs.fontScale==='normal'?'selected':''}>Normal</option><option value="large" ${prefs.fontScale==='large'?'selected':''}>Maior</option></select></div></div><div class="settings-card preference-card"><div class="section-row"><h2>O teu bem-estar digital</h2>${I('shield',22)}</div><p>Tu escolhes quem aparece no teu espaço.</p><div class="safety-counters"><button data-safety>${I('ban',19)}<b>${prefs.blocked.length}</b>pessoas bloqueadas ${I('chevron-right',16)}</button><button data-safety>${I('volume-x',19)}<b>${prefs.muted.length}</b>pessoas silenciadas ${I('chevron-right',16)}</button></div><button class="text-btn" data-hidden-reset>Restaurar ${prefs.hiddenPosts.length} publicações ocultas ${I('undo-2',16)}</button><p class="data-note">O bloqueio oculta conteúdos e impede novas conversas nesta interface. Não é um controlo de acesso no servidor e não torna as tuas publicações privadas.</p></div><div class="settings-card preference-card"><h2>Os teus dados</h2><p>Exporta as tuas coleções e preferências num ficheiro JSON.</p><button class="btn ghost" data-export-data>${I('download',17)}Exportar dados pessoais</button></div>`;}
  function safety(){modal('safety','Um espaço que te faz bem',`<p class="dialog-description">Podes voltar atrás a qualquer momento. Bloquear ou silenciar altera o que vês nesta interface.</p><h3>Pessoas bloqueadas</h3><div class="safety-list">${prefs.blocked.length?prefs.blocked.map(u=>`<div>${avatar(u)}<span><b>${E(user(u).name)}</b><small>@${E(user(u).username)}</small></span>${btn('Desbloquear','data-unblock-user="'+E(u)+'"','btn ghost small')}</div>`).join(''):'<p class="muted">Não bloqueaste ninguém.</p>'}</div><h3>Pessoas silenciadas</h3><div class="safety-list">${prefs.muted.length?prefs.muted.map(u=>`<div>${avatar(u)}<span><b>${E(user(u).name)}</b><small>@${E(user(u).username)}</small></span>${btn('Voltar a ver','data-unmute-user="'+E(u)+'"','btn ghost small')}</div>`).join(''):'<p class="muted">Não silenciaste ninguém.</p>'}</div><p class="info-line">${I('shield',17)}Estes controlos não substituem as regras de privacidade do servidor.</p>`,{kicker:'SEGURANÇA E BEM-ESTAR'});}
  function reportPost(postId){const p=S.posts.find(p=>p.id===postId);if(!p)return;modal('report','O que te preocupa?',`<p class="dialog-description">A tua denúncia é privada e será registada para revisão pelo responsável da comunidade. Não existe moderação automática nesta versão.</p><div class="report-options">${['Assédio ou discurso de ódio','Spam ou conteúdo enganador','Conteúdo impróprio','Violação de privacidade','Outra situação'].map((r,i)=>`<label><input type="radio" name="report-reason" value="${E(r)}" ${i===0?'checked':''}>${E(r)}</label>`).join('')}</div><div class="dialog-actions">${btn('Cancelar','data-close-overlay')}${btn('Enviar denúncia','id="send-report"','btn')}</div>`);Q('#send-report').onclick=e=>run(e.currentTarget,async()=>{await V5DATA.report(p,Q('input[name="report-reason"]:checked').value);closeOverlay();toast(window.PICALTA_DEMO?'Denúncia simulada. Nenhum dado foi enviado.':'Denúncia registada para revisão.');});}
  /* ---------- Pesquisa global e atalhos ---------- */
  const commands=[['feed','house','O teu feed','Voltar aos teus momentos'],['explore','compass','Explorar','Descobrir novas fotografias'],['reels','clapperboard','Reels','Vídeos curtos para ver e criar'],['chats','message-circle','Mensagens','Começar uma conversa'],['collections','bookmark','Coleções','O que guardaste para depois'],['events','calendar-days','Eventos','Encontrar a comunidade'],['challenges','target','Desafios','Pequenos passos, mais XP'],['studio','sliders-horizontal','Estúdio','Rascunhos e estatísticas'],['games','gamepad-2','Jogos','Uma pausa para jogar'],['music','music','Música','Encontra a tua banda sonora'],['groups','users','Comunidades','Pessoas com os mesmos interesses'],['polls','chart-column','Sondagens','Partilha a tua opinião'],['ai','sparkles','PicalAi','A assistente da tua comunidade'],['profile','user','O teu perfil','O teu espaço'],['settings','settings','Definições','O Picalta à tua maneira']];
  function command(){searchMode='Tudo';modal('command','Encontra o teu próximo olhar',`<label class="command-input">${I('search',22)}<input id="command-input" placeholder="Pessoas, fotografias, lugares, ferramentas…" autocomplete="off"><kbd>ESC</kbd></label><div class="command-filters">${['Tudo','Pessoas','Publicações','Ferramentas'].map((c,i)=>`<button class="${i===0?'active':''}" data-command-mode="${c}">${c}</button>`).join('')}</div><div id="command-results" class="command-results"></div><div class="command-footer"><span>↑ ↓ para escolher</span><span>↵ para abrir</span><span>⌘ K para pesquisar</span></div>`,{wide:true,kicker:'PESQUISA RÁPIDA'});Q('#command-input').setAttribute('aria-label','Pesquisar no Picalta');Q('#command-input').oninput=()=>renderCommandResults();renderCommandResults();Q('#command-input').focus();}
  function renderCommandResults(){const input=Q('#command-input');if(!input)return;const term=input.value.trim().toLowerCase();const match=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(term.normalize('NFD').replace(/[\u0300-\u036f]/g,''));let html='';if(searchMode==='Tudo'||searchMode==='Ferramentas'){const list=commands.filter(c=>!term||match(c[2]+' '+c[3]));if(list.length)html+='<h3>NO TEU PICALTA</h3>'+list.slice(0,term?7:5).map(([v,ic,t,desc])=>`<button class="command-result" data-command-nav="${v}">${I(ic,21)}<span><b>${E(t)}</b><small>${E(desc)}</small></span>${I('arrow-right',16)}</button>`).join('');}
    if(searchMode==='Tudo'||searchMode==='Pessoas'){const users=Object.values(S.usersCache).filter(u=>!prefs.blocked.includes(u.uid||u.id)&&(term?match(u.name+' '+u.username):u.uid!==uid())).slice(0,6);if(users.length)html+='<h3>PESSOAS</h3>'+users.map(u=>`<button class="command-result" data-command-profile="${E(u.uid||u.id)}">${avatar(u)}<span><b>${E(u.name)}</b><small>@${E(u.username)}</small></span>${I('arrow-right',16)}</button>`).join('');}
    if((searchMode==='Tudo'||searchMode==='Publicações')&&(term||searchMode==='Publicações')){const ps=S.posts.filter(p=>!prefs.blocked.includes(p.uid)&&match((p.caption||'')+' '+(p.text||'')+' '+(p.location||'')+' '+(p.hashtags||[]).join(' '))).slice(0,8);if(ps.length)html+='<h3>PUBLICAÇÕES</h3>'+ps.map(p=>`<button class="command-result" data-photo-open="${E(p.id)}">${p.imageUrl?`<img class="command-thumb" src="${safeUrl(p.imageUrl)}" alt="">`:I('type',23)}<span><b>${E((p.caption||p.text||'Fotografia').slice(0,80))}</b><small>${E(user(p.uid).name)} · ${E(p.location||'Um momento partilhado')}</small></span>${I('arrow-right',16)}</button>`).join('');}
    Q('#command-results').innerHTML=html||empty('Ainda não encontrámos esse olhar','Experimenta um nome, uma hashtag ou um lugar.','','search');command._selected=-1;}
  function moreMenu(){modal('more','O teu Picalta',`<div class="more-menu-grid">${commands.map(([v,ic,l])=>`<button data-command-nav="${v}">${I(ic,24)}<span>${l}</span></button>`).join('')}</div><div class="more-quick-actions">${btn(I('circle-dot',17)+'Criar história','data-story-create')}${btn(I('moon',17)+'Mudar tema','data-theme-proxy')}${btn(I('bell',17)+'Notificações','data-notif')}</div>`,{drawer:true,kicker:'TUDO NUM SÓ LUGAR'});}
  function help(){modal('help','Há sempre um novo olhar',`<div class="help-intro"><p>O Picalta é o teu espaço para fotografias, conversas e bons encontros.</p></div><div class="help-list"><div><kbd>⌘ / Ctrl + K</kbd><span>Pesquisar em todo o Picalta</span></div><div><kbd>N</kbd><span>Criar uma publicação</span></div><div><kbd>ESC</kbd><span>Fechar a janela atual</span></div><div><kbd>← →</kbd><span>Navegar pelas histórias e fotografias</span></div><div><kbd>↑ ↓</kbd><span>Passar de reel</span></div><div><kbd>M</kbd><span>Ligar ou desligar o som dos reels</span></div><div><kbd>R</kbd><span>Reiniciar o jogo atual</span></div></div><h3>As dez novidades da versão 5</h3><ol class="new-systems"><li>Carrosséis com até seis fotografias</li><li>Editor com filtros, recorte, luz e cor</li><li>Rascunhos automáticos</li><li>Agendamento processado com a app aberta</li><li>Coleções privadas</li><li>Eventos com confirmação de presença</li><li>Desafios diários com recompensas virtuais</li><li>Estatísticas de criador</li><li>Bloquear, silenciar, ocultar e denunciar</li><li>Pesquisa global e atalhos de teclado</li></ol><p class="data-note">${window.PICALTA_DEMO?'Estás numa demonstração isolada, com dados e fotografias fictícios. As alterações são guardadas apenas nesta sessão. Não há envio real de mensagens, denúncias ou emails.':'As funcionalidades ligadas à comunidade utilizam o Firebase configurado nesta instalação. Os envios de fotografias precisam do Cloudinary.'}</p>`,{wide:true,kicker:'AJUDA E NOVIDADES'});}
  function onNavigate(view){if(window.PICALTA_REELS)window.PICALTA_REELS.onNavigate(view);if(!uid())return;const label=commands.find(c=>c[0]===view)?.[2]||'O teu Picalta';Q('#top-section').textContent=label;document.title='Picalta — '+label;window.scrollTo({top:0,behavior:'instant'});if(view==='explore')renderExplore();if(view==='collections')renderCollections();if(view==='events')renderEvents();if(view==='challenges')renderChallenges();if(view==='studio')renderStudio();if(view==='settings')renderPreferences();if(view==='feed')renderFeed();if(view==='profile')setTimeout(()=>{const h=Q('#profile-name');if(h)h.classList.add('profile-title');},0);}
  /* ---------- Perfil ---------- */
  function upgradeProfile(){
    const target=S._profileUid||uid(),u=user(target),grid=Q('#profile-grid'),head=Q('.profile-head');if(!grid||!head)return;
    head.classList.add('p5-profile-head');
    const ts=Q('#top-section');if(ts)ts.textContent=target===uid()?'O teu perfil':'Perfil';
    const posts=S.posts.filter(p=>p.uid===target&&!(p.publishAt&&p.publishAt>Date.now()&&p.uid!==uid()));
    grid.className='profile-grid p5-profile-grid';grid.innerHTML=posts.length?posts.map(exploreTile).join(''):empty(target===uid()?'O teu perfil espera o primeiro momento':'Ainda não há momentos aqui',target===uid()?'Partilha uma fotografia ou um pensamento para dar vida a este espaço.':'Quando partilharem algo, aparecerá aqui.',target===uid()?btn('Criar publicação','data-compose','btn'):'','camera');
    const actions=Q('#profile-actions');if(actions&&target!==uid()&&!actions.querySelector('[data-profile-menu]'))actions.insertAdjacentHTML('beforeend',ib('ellipsis','Mais opções do perfil','data-profile-menu="'+E(target)+'"'));
    if(actions&&target===uid()&&!actions.querySelector('[data-nav="studio"]'))actions.insertAdjacentHTML('beforeend',btn(I('sliders-horizontal',15)+'Estúdio','data-nav="studio"','btn small ghost'));
    const stats=QA('.profile-stats b');if(stats[0])stats[0].textContent=posts.length;
  }
  function profileMenu(target){const blocked=prefs.blocked.includes(target),muted=prefs.muted.includes(target);modal('profilemenu','@'+user(target).username,`<div class="menu-list">${btn(I(muted?'volume-2':'volume-x')+(muted?'Voltar a ver':'Silenciar'),(muted?'data-unmute-user="':'data-mute-user="')+E(target)+'"','menu-row')}${btn(I(blocked?'user-check':'ban')+(blocked?'Desbloquear':'Bloquear'),(blocked?'data-unblock-user="':'data-block-user="')+E(target)+'"','menu-row danger-text')}</div><p class="data-note">Silenciar oculta publicações e histórias. Bloquear também impede iniciar conversas.</p>`,{kicker:'O TEU ESPAÇO, AS TUAS REGRAS'});}
  async function updatePrefs(next,message){const old=prefs;prefs={...prefs,...next};applyPrefs();renderFeed();renderStories();renderPreferences();try{await savePrefs();toast(message);}catch(e){prefs=old;applyPrefs();renderFeed();renderStories();renderPreferences();showError('Não foi possível guardar. Verifica a ligação e tenta novamente.');}}
  const addUnique=(a,x)=>[...new Set([...a,x])];
  function openCommandItem(button){const nav=button.dataset.commandNav,prof=button.dataset.commandProfile;closeOverlay(true);if(nav){navigate(nav);if(nav==='profile')renderMyProfile();if(nav==='games')renderGamesHome();if(nav==='music')renderMusicView();if(nav==='polls')renderPolls();if(nav==='groups'&&window.PICALTA_GROUPS)window.PICALTA_GROUPS.init();if(nav==='explore')renderSuggestions();}if(prof)renderProfile(prof);}
  function theme(){const root=document.documentElement,next=root.dataset.theme==='dark'?'light':'dark';root.dataset.theme=next;const label=Q('#theme-label');if(label)label.textContent=next==='dark'?'Modo claro':'Modo escuro';}
  document.addEventListener('click',async e=>{
    const t=e.target,c=s=>t.closest(s);if(!uid())return;let el;
    if(c('[data-close-overlay]')){closeOverlay();return;}
    if(el=c('[data-compose]')){compose();return;}
    if(el=c('[data-compose-text]')){compose(null,'text');return;}
    if(el=c('[data-compose-mode]')){composer.type=el.dataset.composeMode;composer.caption=Q('#compose-caption')?.value||composer.caption;composer.location=Q('#compose-location')?.value||composer.location;renderComposer();return;}
    if(el=c('[data-story-create]')){createStory();return;}
    if(el=c('[data-command]')){command();return;}
    if(el=c('[data-more]')){moreMenu();return;}
    if(el=c('[data-help]')){help();return;}
    if(el=c('[data-safety]')){safety();return;}
    if(el=c('[data-notif]')){setNotifPanel(true);return;}
    if(el=c('[data-notif-clear]')){S.notifications=[];renderNotifications();setNotifPanel(false);return;}
    if(el=c('[data-theme-proxy]')){theme();return;}
    if(el=c('[data-scroll-stories]')){Q('#people-bar').scrollBy({left:360,behavior:'smooth'});return;}
    if(el=c('[data-feed-tab]')){S.feedTab=el.dataset.feedTab;renderFeed();return;}
    if(el=c('[data-feed-reset]')){S.feedTab='all';S.currentHashtag=null;renderFeed();return;}
    if(el=c('[data-sort-feed]')){feedSort=feedSort==='recent'?'popular':'recent';Q('#feed-sort-label').textContent=feedSort==='recent'?'Recentes':'Mais gostados';renderFeed();return;}
    if(el=c('[data-reload]')){location.reload();return;}
    if(el=c('[data-photo-open]')){e.preventDefault();const pid=el.dataset.photoOpen;if(el.closest('.p-carousel')){clearTimeout(photoOpen._t);photoOpen._t=setTimeout(()=>photoOpen(pid),260);}else photoOpen(pid);return;}
    if(el=c('[data-comments-open]')){comments(el.dataset.commentsOpen);return;}
    if(el=c('[data-post-menu]')){postMenu(el.dataset.postMenu);return;}
    if(el=c('[data-v5-share]')){share(el.dataset.v5Share);return;}
    if(el=c('[data-copy-current]')){copyText(Q('#share-url').value);return;}
    if(el=c('[data-copy-post]')){const u=new URL(location.href);u.hash='post-'+el.dataset.copyPost;copyText(u.href);closeOverlay();return;}
    if(el=c('[data-native-share]')){try{await navigator.share({title:'Picalta',url:Q('#share-url').value});}catch(e){}return;}
    if(el=c('[data-slide]')){slide(el.dataset.slide,Number(el.dataset.dir));return;}
    if(el=c('[data-dot]')){slide(el.dataset.dot,0,Number(el.dataset.index));return;}
    if(el=c('[data-likes-list]')){const p=S.posts.find(x=>x.id===el.dataset.likesList);if(p?.likes?.length)modal('likes','Quem gostou',`<div class="safety-list">${p.likes.map(u=>`<div>${avatar(u)}<span><b>${E(user(u).name)}</b><small>@${E(user(u).username)}</small></span>${btn('Ver perfil','data-goto-profile="'+E(u)+'"','btn ghost small')}</div>`).join('')}</div>`);return;}
    if(el=c('[data-comment-reply]')){replyComment(el.dataset.commentReply,el.dataset.author);return;}
    if(el=c('[data-cancel-reply]')){replyTo=null;Q('#reply-context').hidden=true;return;}
    if(el=c('[data-comment-like]')){const cm=(S.commentsCache[commentPost]||[]).find(x=>x.id===el.dataset.commentLike);if(cm)run(el,()=>V5DATA.commentLike(commentPost,cm));return;}
    if(el=c('[data-comment-edit]')){const cm=(S.commentsCache[commentPost]||[]).find(x=>x.id===el.dataset.commentEdit);if(cm){commentEditing=cm.id;replyTo=null;Q('#p5-comment-input').value=cm.text;Q('#reply-context').hidden=false;Q('#reply-context').innerHTML=`${I('pen-line',15)}A editar o teu comentário<button class="icon-btn" data-cancel-edit aria-label="Cancelar edição">${I('x',16)}</button>`;Q('#p5-comment-input').focus();}return;}
    if(el=c('[data-cancel-edit]')){commentEditing=null;Q('#p5-comment-input').value='';Q('#reply-context').hidden=true;return;}
    if(el=c('[data-comment-delete]')){const cid=el.dataset.commentDelete,post=commentPost;ask('Apagar este comentário?','Também deixará de aparecer na conversa. Esta ação não pode ser desfeita.',async()=>{await V5DATA.commentDelete(post,cid);comments(post);},'Apagar comentário',true);return;}
    if(el=c('[data-comment-mention]')){const i=Q('#p5-comment-input');i.value+=(i.value&&!i.value.endsWith(' ')?' ':'')+'@';i.focus();return;}
    if(el=c('[data-story-prev]')){storyMove(-1);return;}
    if(el=c('[data-story-next]')){storyMove(1);return;}
    if(el=c('[data-story-pause]')){storyState.paused=!storyState.paused;storyState.last=performance.now();renderStory();return;}
    if(el=c('[data-story-delete]')){const sid=el.dataset.storyDelete;if(storyState)storyState.hold=true;ask('Apagar esta história?','Deixará de estar visível para as outras pessoas.',async()=>{await V5DATA.storyDelete(sid);closeOverlay();toast('História apagada.');},'Apagar história',true);return;}
    if(el=c('[data-story-react]')){try{const s=storyState.items[storyState.idx];await V5DATA.storyReact(s.id,el.dataset.storyReact);Q('#story-reaction-status').textContent='Enviaste: '+el.dataset.storyReact;}catch(err){toast('Não foi possível enviar a reação.');}return;}
    if(el=c('[data-photo-edit]')){editPhoto(Number(el.dataset.photoEdit));return;}
    if(el=c('[data-compose-select]')){composer.selected=Number(el.dataset.composeSelect);renderComposerMedia();return;}
    if(el=c('[data-compose-remove]')){composer.images.splice(Number(el.dataset.composeRemove),1);composer.selected=Math.max(0,Math.min(composer.selected,composer.images.length-1));composer.dirty=true;composer.version++;renderComposerMedia();return;}
    if(el=c('[data-compose-move]')){const i=Number(el.dataset.composeMove),j=i+Number(el.dataset.dir),a=composer.images;if(a[j]){[a[i],a[j]]=[a[j],a[i]];composer.selected=j;composer.dirty=true;composer.version++;renderComposerMedia();}return;}
    if(el=c('[data-compose-schedule]')){composer.scheduled=!composer.scheduled;Q('#compose-schedule-panel').hidden=!composer.scheduled;el.classList.toggle('active',composer.scheduled);Q('#compose-publish').innerHTML=composer.scheduled?I('calendar',17)+'Agendar':I('send',17)+'Publicar momento';return;}
    if(el=c('[data-editor-back]')){editor=null;renderComposer();return;}
    if(el=c('[data-editor-filter]')){editor.filter=el.dataset.editorFilter;QA('[data-editor-filter]').forEach(b=>b.classList.toggle('active',b===el));drawEditor();return;}
    if(el=c('[data-editor-ratio]')){editor.ratio=el.dataset.editorRatio;QA('[data-editor-ratio]').forEach(b=>b.classList.toggle('active',b===el));drawEditor();return;}
    if(el=c('[data-editor-rotate]')){editor.rotation+=Number(el.dataset.editorRotate);drawEditor();return;}
    if(el=c('[data-editor-reset]')){Object.assign(editor,{filter:'original',brightness:100,contrast:100,saturation:100,rotation:0,zoom:100,x:0,y:0,ratio:'original'});QA('[data-editor-adjust]').forEach(i=>{i.value=editor[i.dataset.editorAdjust];Q('#out-'+i.dataset.editorAdjust).value=i.value;});QA('[data-editor-filter]').forEach(b=>b.classList.toggle('active',b.dataset.editorFilter==='original'));QA('[data-editor-ratio]').forEach(b=>b.classList.toggle('active',b.dataset.editorRatio==='original'));drawEditor();return;}
    if(el=c('[data-studio-tab]')){renderStudioTab(el.dataset.studioTab);return;}
    if(el=c('[data-draft-open]')){const d=drafts.find(x=>x.id===el.dataset.draftOpen);if(d)compose(d);return;}
    if(el=c('[data-draft-delete]')){const did=el.dataset.draftDelete;ask('Apagar este rascunho?','O rascunho e as fotografias guardadas serão removidos.',async()=>{await V5DATA.draftDelete(did);closeOverlay();toast('Rascunho apagado.');},'Apagar rascunho',true);return;}
    if(el=c('[data-schedule-cancel]')){const sid=el.dataset.scheduleCancel;ask('Cancelar este agendamento?','A publicação não será enviada.',async()=>{await V5DATA.cancelScheduled(sid);closeOverlay();toast('Agendamento cancelado.');},'Cancelar agendamento',true);return;}
    if(el=c('[data-add-collection]')){addToCollection(el.dataset.addCollection);return;}
    if(el=c('[data-collection-create]')){collectionCreate();return;}
    if(el=c('[data-collection-create-for]')){collectionCreate(el.dataset.collectionCreateFor);return;}
    if(el=c('[data-collection-add]')){const post=el.dataset.post,cid=el.dataset.collectionAdd,old=collections;collections=collections.map(x=>x.id===cid?{...x,postIds:x.postIds.includes(post)?x.postIds.filter(p=>p!==post):[...x.postIds,post]}:x);try{await V5DATA.set('collections',{items:collections});if(!S.myFavorites.includes(post)){await dbToggleFavorite(uid(),post,false);S.myFavorites.push(post);renderFeed();}addToCollection(post);}catch(err){collections=old;showError('Não foi possível guardar na coleção.');}return;}
    if(el=c('[data-collection-open]')){openCollection(el.dataset.collectionOpen);return;}
    if(el=c('[data-collection-remove]')){const cid=el.dataset.collectionRemove,post=el.dataset.post,old=collections;collections=collections.map(x=>x.id===cid?{...x,postIds:x.postIds.filter(p=>p!==post)}:x);try{await V5DATA.set('collections',{items:collections});openCollection(cid);renderCollections();}catch(err){collections=old;showError('Não foi possível remover.');}return;}
    if(el=c('[data-collection-menu]')){const col=collections.find(x=>x.id===el.dataset.collectionMenu);modal('collectionmenu',col.name,`<div class="menu-list">${btn(I('pen-line')+'Mudar nome','data-collection-rename="'+E(col.id)+'"','menu-row')}${btn(I('trash-2')+'Apagar coleção','data-collection-delete="'+E(col.id)+'"','menu-row danger-text')}</div><p class="data-note">Apagar a coleção não apaga as publicações originais.</p>`);return;}
    if(el=c('[data-collection-rename]')){const col=collections.find(x=>x.id===el.dataset.collectionRename);nameDialog('Mudar nome',col.name,async name=>{const old=collections;collections=collections.map(x=>x.id===col.id?{...x,name}:x);try{await V5DATA.set('collections',{items:collections});}catch(err){collections=old;throw err;}});return;}
    if(el=c('[data-collection-delete]')){const col=collections.find(x=>x.id===el.dataset.collectionDelete);ask('Apagar esta coleção?','As publicações não serão apagadas, apenas deixam de estar organizadas aqui.',async()=>{const old=collections;collections=collections.filter(x=>x.id!==col.id);try{await V5DATA.set('collections',{items:collections});closeOverlay();renderCollections();toast('Coleção apagada.');}catch(err){collections=old;throw err;}},'Apagar coleção',true);return;}
    if(el=c('[data-collection-filter]')){collectionFilter=el.dataset.collectionFilter;renderCollections();return;}
    if(el=c('[data-explore-filter]')){exploreFilter=el.dataset.exploreFilter;renderExplore();return;}
    if(el=c('[data-event-create]')){createEvent();return;}
    if(el=c('[data-event-open]')){openEvent(el.dataset.eventOpen);return;}
    if(el=c('[data-event-rsvp]')){rsvp(el.dataset.eventRsvp,el);return;}
    if(el=c('[data-event-ics]')){downloadICS(el.dataset.eventIcs);return;}
    if(el=c('[data-event-filter]')){eventFilter=el.dataset.eventFilter;renderEvents();return;}
    if(el=c('[data-challenge-start]')){const id0=el.dataset.challengeStart;if(id0==='photo')compose();if(id0==='comment')navigate('feed'),renderFeed();if(id0==='discover')navigate('explore');if(id0==='story')createStory();return;}
    if(el=c('[data-challenge-claim]')){const key=el.dataset.challengeClaim,def=challenges.find(x=>x.id===key);await run(el,async()=>{const ok=await V5DATA.claimChallenge(key,def.reward,privateDate());if(ok){daily={...daily,claimed:[...(daily.claimed||[]),key]};S.player.xp=(S.player.xp||0)+def.reward;S.player.level=levelForXp(S.player.xp);renderXpBar();toast('+'+def.reward+' XP recolhidos.');renderChallenges();renderChallengeRail();}else showError('Esta recompensa já foi recolhida ou ainda não está concluída.');});return;}
    if(el=c('[data-edit-caption]')){editCaption(el.dataset.editCaption);return;}
    if(el=c('[data-caption-save]')){const p=S.posts.find(x=>x.id===el.dataset.captionSave),text=Q('#edit-caption').value.trim();if(!p)return;await run(el,async()=>{if(!text&&!p.imageUrl)throw new Error('O pensamento não pode ficar vazio.');const field=p.imageUrl?'caption':'text';await __fsFns.updateDoc(__fsFns.doc(db,'posts',p.id),{[field]:text,hashtags:[...new Set(text.match(/#[\p{L}\p{N}_]+/gu)||[])]});closeOverlay();toast('Publicação atualizada.');});return;}
    if(el=c('[data-hide-post]')){const post=el.dataset.hidePost;updatePrefs({hiddenPosts:addUnique(prefs.hiddenPosts,post)},'Publicação ocultada. Podes restaurá-la nas definições.');closeOverlay();return;}
    if(el=c('[data-hidden-reset]')){updatePrefs({hiddenPosts:[]},'As publicações ocultas foram restauradas.');return;}
    if(el=c('[data-mute-user]')){const u=el.dataset.muteUser;updatePrefs({muted:addUnique(prefs.muted,u)},'Silenciaste @'+user(u).username+'.');closeOverlay();return;}
    if(el=c('[data-unmute-user]')){const u=el.dataset.unmuteUser;updatePrefs({muted:prefs.muted.filter(x=>x!==u)},'Voltas a ver @'+user(u).username+'.');closeOverlay();return;}
    if(el=c('[data-block-user]')){const u=el.dataset.blockUser;ask('Bloquear @'+user(u).username+'?','Deixarás de ver as publicações, comentários e histórias desta pessoa. Podes desbloquear nas definições.',async()=>{await updatePrefs({blocked:addUnique(prefs.blocked,u),muted:prefs.muted.filter(x=>x!==u)},'Pessoa bloqueada.');closeOverlay();},'Bloquear',true);return;}
    if(el=c('[data-unblock-user]')){const u=el.dataset.unblockUser;updatePrefs({blocked:prefs.blocked.filter(x=>x!==u)},'Pessoa desbloqueada.');if(activeOverlay)closeOverlay();return;}
    if(el=c('[data-report-post]')){reportPost(el.dataset.reportPost);return;}
    if(el=c('[data-profile-menu]')){profileMenu(el.dataset.profileMenu);return;}
    if(el=c('[data-export-data]')){download(new Blob([JSON.stringify({exportadoEm:new Date().toISOString(),preferencias:prefs,colecoes:collections,favoritos:S.myFavorites,progresso:{xp:S.player.xp,nivel:S.player.level}},null,2)],{type:'application/json'}),'picalta-dados.json');toast('Ficheiro exportado.');return;}
    if(el=c('[data-command-nav],[data-command-profile]')){openCommandItem(el);return;}
    if(el=c('[data-command-mode]')){searchMode=el.dataset.commandMode;QA('[data-command-mode]').forEach(b=>b.classList.toggle('active',b===el));renderCommandResults();return;}
    if(el=c('[data-v5-follow]')){const target=el.dataset.v5Follow;await run(el,async()=>{const cur=S.myFollowing.includes(target),now=await dbToggleFollow(target,uid(),cur);if(now&&!cur){S.myFollowing.push(target);xpOnFollow();}if(!now)S.myFollowing=S.myFollowing.filter(x=>x!==target);renderSuggestedRail();toast(now?'A seguir.':'Deixaste de seguir.');});return;}
    if(c('[data-goto-profile],[data-start-chat],[data-nav]'))closeOverlay(true);
    if(el=c('[data-lightbox-zoom]')){Q('.lightbox-photo')?.classList.toggle('zoomed');return;}
  });
  document.addEventListener('click',e=>{const b=e.target.closest('[data-start-chat]');if(b&&prefs.blocked.includes(b.dataset.startChat)){e.preventDefault();e.stopImmediatePropagation();toast('Desbloqueia esta pessoa para conversar.');}},true);
  document.addEventListener('dblclick',e=>{const car=e.target.closest('.p-carousel');if(!car||!uid())return;clearTimeout(photoOpen._t);const p=S.posts.find(x=>x.id===car.dataset.carousel);if(!p)return;const d=car.querySelector('.double-like');d.classList.remove('play');void d.offsetWidth;d.classList.add('play');if(!(p.likes||[]).includes(uid()))like(p.id);});
  document.addEventListener('change',async e=>{const el=e.target.closest('[data-pref]');if(!el)return;const key=el.dataset.pref;await updatePrefs({[key]:el.type==='checkbox'?el.checked:el.value},'Preferência guardada.');});
  document.addEventListener('keydown',e=>{
    if(!uid())return;const typing=/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName)||document.activeElement?.isContentEditable;
    if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();command();return;}
    if(e.key==='Escape'&&activeOverlay){e.preventDefault();closeOverlay();return;}
    if(e.key==='Escape'&&!activeOverlay){try{setNotifPanel(false);}catch(_){}}
    if(activeOverlay==='story'&&!typing){if(e.key==='ArrowRight')storyMove(1);if(e.key==='ArrowLeft')storyMove(-1);if(e.key===' '){e.preventDefault();storyState.paused=!storyState.paused;renderStory();}}
    if((activeOverlay==='lightbox')&&!typing&&['ArrowLeft','ArrowRight'].includes(e.key)){const id0=Q('[data-slide]')?.dataset.slide;if(id0)slide(id0,e.key==='ArrowRight'?1:-1);}
    if(activeOverlay==='command'){const items=QA('.command-result');if(['ArrowDown','ArrowUp'].includes(e.key)&&items.length){e.preventDefault();command._selected=(command._selected+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items.forEach((x,i)=>x.classList.toggle('active',i===command._selected));items[command._selected].scrollIntoView({block:'nearest'});}if(e.key==='Enter'&&command._selected>=0){e.preventDefault();items[command._selected].click();}}
    if(activeOverlay&&e.key==='Tab'){const d=Q('.p-dialog');const f=[...d.querySelectorAll('button:not([disabled]),input:not([hidden]),textarea,select,a[href],[tabindex]:not([tabindex="-1"])')].filter(x=>x.offsetParent!==null);if(!f.length)return;const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
    if(!typing&&!activeOverlay&&e.key.toLowerCase()==='n'&&!e.metaKey&&!e.ctrlKey&&!e.altKey){e.preventDefault();compose();}
  });
  window.addEventListener('beforeunload',e=>{if(composer?.dirty&&activeOverlay==='composer'){e.preventDefault();e.returnValue='';}});
  window.PICALTA_V5={h:{modal,closeOverlay,run,ask,btn,ib,empty,avatar,user,safeUrl,E,I,tick:tickChallenge,comments,postMenu,share,like,prefs:()=>prefs,uid,get overlay(){return activeOverlay;}},init,onNavigate:v=>{onNavigate(v);if(v==='profile')upgradeProfile();},renderStories,renderFeed,compose,story,like,deletePost,comments,renderAccount,challengeDefs:challenges};
  window.PICALTA_V5_SETUP=setup;
  const origRenderProfile=window.renderProfile;
  document.addEventListener('DOMContentLoaded',()=>{});
  setup();
})();
